INSERT INTO `learning_categories` (`slug`,`name`,`is_active`,`created_at`,`updated_at`) VALUES ('ec-ngu','Tiếng Anh nền tảng',1,'2026-10-22 09:50:59','2026-10-22 09:50:59') ON DUPLICATE KEY UPDATE `id`=`learning_categories`.`id`;
INSERT INTO `courses` (`learning_category_id`,`code`,`name`,`slug`,`delivery_mode`,`summary`,`description`,`duration_hours`,`price`,`access_days`,`is_active`,`is_for_sale`,`published_at`,`learning_outcomes`,`created_at`,`updated_at`) SELECT cat.id,'EC-GRAMMAR','Ngữ pháp nền tảng: từ câu đơn đến đoạn ngắn','ngu-phap-nen-tang','online','Ba bài học về cấu trúc câu, sự hòa hợp chủ ngữ và thì hiện tại, kèm đề luyện có đáp án.','Ba bài học về cấu trúc câu, sự hòa hợp chủ ngữ và thì hiện tại, kèm đề luyện có đáp án.\n\nKhóa mẫu do English Center tự biên soạn. Nội dung học và đề luyện được lưu ngay trong hệ thống. Có ba bài học, bài tập áp dụng và một đề tổng kết gồm sáu câu kèm lời giải. Thanh toán trong bản này là mô phỏng, không thu tiền thật.',3,199000,365,1,1,'2026-10-22 09:50:59','["Viết được câu đơn có đủ chủ ngữ và động từ.","Phân biệt hiện tại đơn và hiện tại tiếp diễn.","Tự sửa các lỗi hòa hợp chủ ngữ và động từ."]','2026-10-22 09:50:59','2026-10-22 09:50:59' FROM learning_categories cat WHERE cat.slug='ec-ngu' ON DUPLICATE KEY UPDATE `id`=`courses`.`id`;
INSERT INTO `course_sections` (`course_id`,`title`,`position`,`created_at`,`updated_at`) SELECT c.id,'Lộ trình học và thực hành',1,'2026-10-22 09:50:59','2026-10-22 09:50:59' FROM courses c WHERE c.code='EC-GRAMMAR' ON DUPLICATE KEY UPDATE `id`=`course_sections`.`id`;
INSERT INTO `lessons` (`course_section_id`,`title`,`slug`,`content`,`position`,`type`,`duration_seconds`,`is_published`,`created_at`,`updated_at`) SELECT s.id,'Câu đơn và thành phần cơ bản','cau-don','MỤC TIÊU\nNhận ra chủ ngữ, động từ và thành phần bổ sung trong câu đơn.\n\n1. Cấu trúc cốt lõi\nMột câu hoàn chỉnh thường cần chủ ngữ và động từ đã chia. Trong ‘Lan studies every evening’, Lan là chủ ngữ, studies là động từ, every evening là trạng ngữ thời gian.\n\n2. Khi nào câu cần tân ngữ?\nĐộng từ như enjoy hoặc buy thường cần đối tượng: ‘We enjoy music’. Ngược lại, ‘The baby sleeps’ đã đủ nghĩa. Sau be thường là danh từ, tính từ hoặc cụm giới từ: ‘My sister is a nurse’, ‘The room is quiet’.\n\n3. Tránh câu thiếu thành phần\n‘Because the lesson is useful’ chỉ là mệnh đề phụ. Có thể hoàn chỉnh thành ‘I take notes because the lesson is useful’. Không nối hai câu độc lập chỉ bằng dấu phẩy; hãy dùng dấu chấm hoặc liên từ phù hợp.\n\nTHỰC HÀNH\nViết ba câu về việc học. Gạch chân chủ ngữ, khoanh động từ. Với mỗi câu, tự hỏi: động từ đã chia chưa và ý chính đã hoàn chỉnh chưa?\n\nGỢI Ý TỰ KIỂM TRA\n‘I study English every day.’ / ‘My desk is small.’ / ‘I read short stories because they are interesting.’',1,'text',1200,1,'2026-10-22 09:50:59','2026-10-22 09:50:59' FROM course_sections s JOIN courses c ON c.id=s.course_id WHERE c.code='EC-GRAMMAR' AND s.position=1 ON DUPLICATE KEY UPDATE `id`=`lessons`.`id`;
INSERT INTO `lessons` (`course_section_id`,`title`,`slug`,`content`,`position`,`type`,`duration_seconds`,`is_published`,`created_at`,`updated_at`) SELECT s.id,'Chủ ngữ và động từ phải hòa hợp','hoa-hop-chu-ngu','MỤC TIÊU\nChọn đúng dạng động từ theo chủ ngữ ở thì hiện tại đơn.\n\n1. Xác định chủ ngữ chính\nVới he, she, it hoặc danh từ số ít, động từ thường thêm -s/-es: ‘The student reads’. Với I, you, we, they hoặc danh từ số nhiều, dùng dạng cơ bản: ‘The students read’. Riêng be có am, is, are.\n\n2. Đừng bị cụm bổ sung đánh lạc hướng\nTrong ‘The list of tasks is long’, chủ ngữ chính là list, không phải tasks. Cụm ‘of tasks’ bổ nghĩa cho list. Vì list là số ít nên dùng is.\n\n3. Câu phủ định và nghi vấn\nDùng does với chủ ngữ ngôi ba số ít, đưa động từ chính về dạng cơ bản: ‘She does not work on Sunday’, ‘Does he speak English?’ Không viết ‘Does he speaks’.\n\nTHỰC HÀNH\nĐiền động từ: 1. My brother ___ (study) at home. 2. The books ___ (be) on the desk. 3. Does Anna ___ (like) tea?\n\nĐÁP ÁN VÀ GIẢI THÍCH\n1. studies: brother là số ít, study đổi y thành ies. 2. are: books là số nhiều. 3. like: sau does dùng nguyên mẫu không to.\n\nHãy tự viết thêm một cặp câu với danh từ số ít và số nhiều.',2,'text',1200,1,'2026-10-22 09:50:59','2026-10-22 09:50:59' FROM course_sections s JOIN courses c ON c.id=s.course_id WHERE c.code='EC-GRAMMAR' AND s.position=1 ON DUPLICATE KEY UPDATE `id`=`lessons`.`id`;
INSERT INTO `lessons` (`course_section_id`,`title`,`slug`,`content`,`position`,`type`,`duration_seconds`,`is_published`,`created_at`,`updated_at`) SELECT s.id,'Hiện tại đơn, tiếp diễn và bài tổng kết','thi-hien-tai','MỤC TIÊU\nPhân biệt thói quen với hành động đang diễn ra.\n\n1. Hiện tại đơn\nDùng cho thói quen hoặc sự thật tương đối ổn định: ‘I usually walk to school’. Các dấu hiệu thường gặp gồm usually, often, every day. Dấu hiệu chỉ là gợi ý; cần hiểu ngữ cảnh.\n\n2. Hiện tại tiếp diễn\nCấu trúc am/is/are + V-ing, dùng cho hành động đang diễn ra hoặc tình huống tạm thời: ‘I am reading now’. Không quên động từ be.\n\n3. So sánh trong cùng tình huống\n‘Mai works in a library’ nói về công việc thường lệ. ‘Mai is working from home this week’ nói về thay đổi tạm thời. Một số động từ trạng thái như know, believe thường dùng dạng đơn trong nghĩa thông dụng.\n\nBÀI TỔNG KẾT\nViết một đoạn 4 câu: hai câu về thói quen học và hai câu về việc đang làm hôm nay. Kiểm tra thứ tự từ, động từ be và đuôi -s.\n\nMẪU\n‘I study English after dinner. My friend helps me with vocabulary. Today, I am reviewing a short lesson. We are preparing for a practice test.’\n\nMở đề luyện kèm bên dưới để tự kiểm tra sáu câu. Sau khi nộp, đọc lời giải từng câu rồi đánh dấu hoàn thành bài.',3,'text',1200,1,'2026-10-22 09:50:59','2026-10-22 09:50:59' FROM course_sections s JOIN courses c ON c.id=s.course_id WHERE c.code='EC-GRAMMAR' AND s.position=1 ON DUPLICATE KEY UPDATE `id`=`lessons`.`id`;
INSERT INTO `exam_papers` (`learning_category_id`,`slug`,`title`,`description`,`skill`,`duration_seconds`,`status`,`published_at`,`created_at`,`updated_at`) SELECT cat.id,'ec-grammar-practice-01','Đề luyện ngữ pháp nền tảng 01','Đề luyện tự biên soạn, sáu câu có đáp án và giải thích. Không phải đề thi chứng chỉ chính thức.','reading',900,'published','2026-10-22 09:50:59','2026-10-22 09:50:59','2026-10-22 09:50:59' FROM learning_categories cat WHERE cat.slug='ec-ngu' ON DUPLICATE KEY UPDATE `id`=`exam_papers`.`id`;
INSERT INTO `exam_sections` (`exam_paper_id`,`position`,`title`,`skill`,`instructions`,`created_at`,`updated_at`) SELECT p.id,1,'Phần luyện tập','reading','Đọc kỹ câu hỏi và chọn một đáp án đúng.','2026-10-22 09:50:59','2026-10-22 09:50:59' FROM exam_papers p WHERE p.slug='ec-grammar-practice-01' ON DUPLICATE KEY UPDATE `id`=`exam_sections`.`id`;
INSERT INTO `question_groups` (`exam_section_id`,`position`,`title`,`instructions`,`created_at`,`updated_at`) SELECT s.id,1,'Câu hỏi tổng kết','Mỗi câu chọn một đáp án.','2026-10-22 09:50:59','2026-10-22 09:50:59' FROM exam_sections s JOIN exam_papers p ON p.id=s.exam_paper_id WHERE p.slug='ec-grammar-practice-01' AND s.position=1 ON DUPLICATE KEY UPDATE `id`=`question_groups`.`id`;
INSERT INTO `questions` (`question_group_id`,`exam_section_id`,`position`,`prompt`,`type`,`max_points`,`created_at`,`updated_at`) SELECT g.id,s.id,1,'The list of activities ___ on the board.','single_choice',1,'2026-10-22 09:50:59','2026-10-22 09:50:59' FROM question_groups g JOIN exam_sections s ON s.id=g.exam_section_id JOIN exam_papers p ON p.id=s.exam_paper_id WHERE p.slug='ec-grammar-practice-01' AND s.position=1 AND g.position=1 ON DUPLICATE KEY UPDATE `id`=`questions`.`id`;
INSERT INTO `question_options` (`question_id`,`label`,`content`,`position`,`created_at`,`updated_at`) SELECT q.id,'A','is',1,'2026-10-22 09:50:59','2026-10-22 09:50:59' FROM questions q JOIN question_groups g ON g.id=q.question_group_id JOIN exam_sections s ON s.id=g.exam_section_id JOIN exam_papers p ON p.id=s.exam_paper_id WHERE p.slug='ec-grammar-practice-01' AND s.position=1 AND g.position=1 AND q.position=1 ON DUPLICATE KEY UPDATE `id`=`question_options`.`id`;
