INSERT INTO `learning_categories` (`slug`,`name`,`is_active`,`created_at`,`updated_at`) VALUES ('ec-ielts','IELTS Academic',1,'2026-10-22 09:50:59','2026-10-22 09:50:59') ON DUPLICATE KEY UPDATE `id`=`learning_categories`.`id`;
INSERT INTO `courses` (`learning_category_id`,`code`,`name`,`slug`,`delivery_mode`,`summary`,`description`,`duration_hours`,`price`,`access_days`,`is_active`,`is_for_sale`,`published_at`,`learning_outcomes`,`created_at`,`updated_at`) SELECT cat.id,'EC-IELTS-READ','IELTS Reading nhập môn: đọc tìm ý và chứng cứ','ielts-reading-nhap-mon','online','Ba bài học về skimming, scanning và kiểm tra thông tin, kèm đoạn đọc và đề luyện tự biên soạn.','Ba bài học về skimming, scanning và kiểm tra thông tin, kèm đoạn đọc và đề luyện tự biên soạn.\n\nKhóa mẫu do English Center tự biên soạn. Nội dung học và đề luyện được lưu ngay trong hệ thống. Có ba bài học, bài tập áp dụng và một đề tổng kết gồm sáu câu kèm lời giải. Thanh toán trong bản này là mô phỏng, không thu tiền thật.',3,299000,365,1,1,'2026-10-22 09:50:59','["Phân biệt đọc lấy ý chính với đọc tìm thông tin cụ thể.","Dùng chứng cứ để phân loại True, False và Not Given.","Tuân thủ giới hạn từ khi trả lời câu hỏi."]','2026-10-22 09:50:59','2026-10-22 09:50:59' FROM learning_categories cat WHERE cat.slug='ec-ielts' ON DUPLICATE KEY UPDATE `id`=`courses`.`id`;
INSERT INTO `course_sections` (`course_id`,`title`,`position`,`created_at`,`updated_at`) SELECT c.id,'Lộ trình học và thực hành',1,'2026-10-22 09:50:59','2026-10-22 09:50:59' FROM courses c WHERE c.code='EC-IELTS-READ' ON DUPLICATE KEY UPDATE `id`=`course_sections`.`id`;
INSERT INTO `lessons` (`course_section_id`,`title`,`slug`,`content`,`position`,`type`,`duration_seconds`,`is_published`,`created_at`,`updated_at`) SELECT s.id,'Skimming và scanning','skimming-scanning','MỤC TIÊU\nChọn cách đọc phù hợp với yêu cầu câu hỏi.\n\nSKIMMING\nĐọc nhanh tiêu đề, câu mở đầu và các từ lặp lại để nắm chủ đề. Không cố dịch từng từ. Hãy tóm tắt mỗi đoạn bằng vài từ khóa.\n\nSCANNING\nĐọc tìm tên riêng, năm, con số hoặc cách diễn đạt tương đương với từ khóa câu hỏi. Khi thấy vị trí có thể chứa đáp án, đọc kỹ cả câu và câu liền kề.\n\nĐOẠN ĐỌC\n‘In 2022, Brook Town opened a community garden on unused land near the station. Residents grow vegetables in shared plots. The garden also runs free workshops on Saturday mornings. A small tool shed was added in 2023. Organizers hope the project will help neighbors meet one another.’\n\nTHỰC HÀNH\n1. Tóm tắt mục đích chung của đoạn. 2. Vườn mở năm nào? 3. Hoạt động nào diễn ra sáng thứ Bảy?\n\nĐÁP ÁN\nĐoạn giới thiệu một vườn cộng đồng và hoạt động của nó. Vườn mở năm 2022. Các buổi workshop miễn phí diễn ra sáng thứ Bảy.\n\nLƯU Ý\nNăm 2023 chỉ thời điểm thêm nhà kho dụng cụ; không phải năm mở vườn.',1,'text',1200,1,'2026-10-22 09:50:59','2026-10-22 09:50:59' FROM course_sections s JOIN courses c ON c.id=s.course_id WHERE c.code='EC-IELTS-READ' AND s.position=1 ON DUPLICATE KEY UPDATE `id`=`lessons`.`id`;
INSERT INTO `lessons` (`course_section_id`,`title`,`slug`,`content`,`position`,`type`,`duration_seconds`,`is_published`,`created_at`,`updated_at`) SELECT s.id,'True, False và Not Given','true-false-not-given','MỤC TIÊU\nĐánh giá một nhận định dựa trên thông tin có trong bài đọc.\n\nTRUE\nBài đọc xác nhận cùng ý với nhận định, dù dùng từ khác.\n\nFALSE\nBài đọc có thông tin mâu thuẫn với nhận định.\n\nNOT GIVEN\nBài đọc không đủ thông tin để kết luận. Không dùng kiến thức ngoài bài.\n\nĐOẠN ĐỌC\n‘The community garden offers free workshops on Saturday mornings. Participants must book a place in advance. The organizers provide basic tools.’\n\nPHÂN TÍCH\n1. ‘The workshops cost nothing.’ là TRUE vì free tương đương cost nothing.\n2. ‘Participants can attend without booking.’ là FALSE vì must book in advance mâu thuẫn với without booking.\n3. ‘Every participant lives in Brook Town.’ là NOT GIVEN vì đoạn không đề cập nơi ở của tất cả người tham gia.\n\nCÁCH LÀM\nGạch chân từ chỉ phạm vi như all, every, only, sometimes. Tìm chứng cứ rồi so sánh cả ý, không chỉ một từ trùng nhau. Ghi số câu hoặc vị trí chứa chứng cứ khi ôn lỗi sai.',2,'text',1200,1,'2026-10-22 09:50:59','2026-10-22 09:50:59' FROM course_sections s JOIN courses c ON c.id=s.course_id WHERE c.code='EC-IELTS-READ' AND s.position=1 ON DUPLICATE KEY UPDATE `id`=`lessons`.`id`;
INSERT INTO `lessons` (`course_section_id`,`title`,`slug`,`content`,`position`,`type`,`duration_seconds`,`is_published`,`created_at`,`updated_at`) SELECT s.id,'Giới hạn từ và bài luyện tổng kết','gioi-han-tu','MỤC TIÊU\nTrả lời đúng thông tin và đúng yêu cầu số từ.\n\nĐỌC CHỈ DẪN TRƯỚC\nNếu đề ghi NO MORE THAN TWO WORDS, câu trả lời tối đa hai từ. Không chép cả câu khi chỉ cần một cụm ngắn. Đếm từ và kiểm tra chính tả trước khi nộp.\n\nVÍ DỤ\nBài đọc: ‘The new garden is near the railway station.’\nCâu hỏi: The garden is near the _____. Giới hạn: NO MORE THAN TWO WORDS.\nĐáp án: railway station. Chép ‘the railway station’ sẽ vượt giới hạn hai từ.\n\nQUY TRÌNH TỔNG KẾT\nBước 1: đọc câu hỏi và chỉ dẫn. Bước 2: xác định từ khóa. Bước 3: quét tìm vị trí trong bài. Bước 4: đọc kỹ chứng cứ. Bước 5: kiểm tra số từ và chính tả.\n\nTHỰC HÀNH\nViết một bản tóm tắt ba ý về vườn cộng đồng từ bài trước: năm mở, hoạt động miễn phí và cách đăng ký. Sau đó làm đề luyện bên dưới.\n\nGHI CHÚ\nĐề luyện của khóa là nội dung tự biên soạn phục vụ nhập môn, không phải đề IELTS chính thức và không quy đổi trực tiếp thành band IELTS.',3,'text',1200,1,'2026-10-22 09:50:59','2026-10-22 09:50:59' FROM course_sections s JOIN courses c ON c.id=s.course_id WHERE c.code='EC-IELTS-READ' AND s.position=1 ON DUPLICATE KEY UPDATE `id`=`lessons`.`id`;
