INSERT INTO `learning_categories` (`slug`,`name`,`is_active`,`created_at`,`updated_at`) VALUES ('catalog-combo','Combo đặc biệt',1,'2026-10-22 09:50:59','2026-10-22 09:50:59') ON DUPLICATE KEY UPDATE `id`=`learning_categories`.`id`;
INSERT INTO `courses` (`learning_category_id`,`code`,`catalog_key`,`slug`,`name`,`summary`,`description`,`audience`,`learning_outcomes`,`curriculum_outline`,`thumbnail_path`,`price`,`sale_price`,`intro_video_url`,`delivery_mode`,`is_active`,`is_for_sale`,`published_at`,`duration_hours`,`access_days`,`created_at`,`updated_at`) SELECT cat.id,'EC-CAT-SERIES-7','series-7','chuong-trinh-series-7','Combo TOEIC 4 kỹ năng','Lộ trình kết hợp nghe, đọc, nói và viết TOEIC trong cùng một nhóm khóa học.','Lộ trình kết hợp nghe, đọc, nói và viết TOEIC trong cùng một nhóm khóa học.\n\nCách học\nBắt đầu bằng việc xác định mục tiêu, đọc các chủ đề trong chương trình và chia thời gian học thành những buổi ngắn. Sau mỗi buổi, ghi lại kiến thức mới, tự giải thích bằng ví dụ của bản thân và ôn lại nội dung còn chưa chắc.\n\nHọc và luyện tập\nCác bài học được công bố sẽ xuất hiện trong chương trình học bên dưới. Khi khóa học được mở bán, bạn thêm vào giỏ, xác nhận thanh toán mô phỏng và truy cập từ mục Khóa học của tôi. Bài học và tiến độ được quản lý ngay trên English Center.','Người muốn kết hợp nhiều kỹ năng trong một lộ trình, học từ nền tảng đến thực hành theo từng chủ đề.','["Kết hợp nhiều kỹ năng trong một kế hoạch học thống nhất.","Củng cố nền tảng trước khi chuyển sang các chủ đề nâng cao.","Phân bổ thời gian học, ôn tập và tự đánh giá theo từng giai đoạn."]','["[Complete TOEIC] Chiến lược làm bài - Từ vựng - Ngữ pháp - Luyện nghe với Dictation [Tặng TED Talks]","[TOEIC SW] TOEIC Speaking and Writing [Tặng TED Talks]"]','images/catalog/study4/series-7.webp',3956000,1650000,'https://youtu.be/QV-X5DpteLk','online',1,0,'2026-10-22 09:50:59',1,365,'2026-10-22 09:50:59','2026-10-22 09:50:59' FROM learning_categories cat WHERE cat.slug='catalog-combo' ON DUPLICATE KEY UPDATE `id`=`courses`.`id`;
INSERT INTO `learning_categories` (`slug`,`name`,`is_active`,`created_at`,`updated_at`) VALUES ('catalog-combo','Combo đặc biệt',1,'2026-10-22 09:50:59','2026-10-22 09:50:59') ON DUPLICATE KEY UPDATE `id`=`learning_categories`.`id`;
INSERT INTO `courses` (`learning_category_id`,`code`,`catalog_key`,`slug`,`name`,`summary`,`description`,`audience`,`learning_outcomes`,`curriculum_outline`,`thumbnail_path`,`price`,`sale_price`,`intro_video_url`,`delivery_mode`,`is_active`,`is_for_sale`,`published_at`,`duration_hours`,`access_days`,`created_at`,`updated_at`) SELECT cat.id,'EC-CAT-SERIES-2','series-2','chuong-trinh-series-2','Combo 4 kỹ năng IELTS Intensive','Nhóm khóa IELTS Intensive bao quát bốn kỹ năng nghe, đọc, nói và viết.','Nhóm khóa IELTS Intensive bao quát bốn kỹ năng nghe, đọc, nói và viết.\n\nCách học\nBắt đầu bằng việc xác định mục tiêu, đọc các chủ đề trong chương trình và chia thời gian học thành những buổi ngắn. Sau mỗi buổi, ghi lại kiến thức mới, tự giải thích bằng ví dụ của bản thân và ôn lại nội dung còn chưa chắc.\n\nHọc và luyện tập\nCác bài học được công bố sẽ xuất hiện trong chương trình học bên dưới. Khi khóa học được mở bán, bạn thêm vào giỏ, xác nhận thanh toán mô phỏng và truy cập từ mục Khóa học của tôi. Bài học và tiến độ được quản lý ngay trên English Center.','Người muốn kết hợp nhiều kỹ năng trong một lộ trình, học từ nền tảng đến thực hành theo từng chủ đề.','["Kết hợp nhiều kỹ năng trong một kế hoạch học thống nhất.","Củng cố nền tảng trước khi chuyển sang các chủ đề nâng cao.","Phân bổ thời gian học, ôn tập và tự đánh giá theo từng giai đoạn."]','["[IELTS Intensive Listening] Chiến lược làm bài - Chữa đề - Luyện nghe IELTS Listening theo phương pháp Dictation","[IELTS Intensive Reading] Chiến lược làm bài - Chữa đề - Từ vựng IELTS Reading","[IELTS Intensive Speaking] Thực hành luyện tập IELTS Speaking","[IELTS Intensive Writing] Thực hành luyện tập IELTS Writing"]','images/catalog/study4/series-2.webp',3956000,1650000,'https://youtu.be/__nzODTNbjM','online',1,0,'2026-10-22 09:50:59',1,365,'2026-10-22 09:50:59','2026-10-22 09:50:59' FROM learning_categories cat WHERE cat.slug='catalog-combo' ON DUPLICATE KEY UPDATE `id`=`courses`.`id`;
