LICATE KEY UPDATE `id`=`courses`.`id`;
INSERT INTO `learning_categories` (`slug`,`name`,`is_active`,`created_at`,`updated_at`) VALUES ('catalog-combo','Combo đặc biệt',1,'2026-10-22 09:50:59','2026-10-22 09:50:59') ON DUPLICATE KEY UPDATE `id`=`learning_categories`.`id`;
INSERT INTO `courses` (`learning_category_id`,`code`,`catalog_key`,`slug`,`name`,`summary`,`description`,`audience`,`learning_outcomes`,`curriculum_outline`,`thumbnail_path`,`price`,`sale_price`,`intro_video_url`,`delivery_mode`,`is_active`,`is_for_sale`,`published_at`,`duration_hours`,`access_days`,`created_at`,`updated_at`) SELECT cat.id,'EC-CAT-SERIES-1','series-1','chuong-trinh-series-1','Combo Practical English - Thực hành tiếng Anh online','Nhóm khóa thực hành tiếng Anh, kết hợp từ vựng, ngữ pháp và hoạt động nghe nói.','Nhóm khóa thực hành tiếng Anh, kết hợp từ vựng, ngữ pháp và hoạt động nghe nói.\n\nCách học\nBắt đầu bằng việc xác định mục tiêu, đọc các chủ đề trong chương trình và chia thời gian học thành những buổi ngắn. Sau mỗi buổi, ghi lại kiến thức mới, tự giải thích bằng ví dụ của bản thân và ôn lại nội dung còn chưa chắc.\n\nHọc và luyện tập\nCác bài học được công bố sẽ xuất hiện trong chương trình học bên dưới. Khi khóa học được mở bán, bạn thêm vào giỏ, xác nhận thanh toán mô phỏng và truy cập từ mục Khóa học của tôi. Bài học và tiến độ được quản lý ngay trên English Center.','Người muốn kết hợp nhiều kỹ năng trong một lộ trình, học từ nền tảng đến thực hành theo từng chủ đề.','["Kết hợp nhiều kỹ năng trong một kế hoạch học thống nhất.","Củng cố nền tảng trước khi chuyển sang các chủ đề nâng cao.","Phân bổ thời gian học, ôn tập và tự đánh giá theo từng giai đoạn."]','["[Practical English] 3600 từ vựng tiếng Anh thông dụng","[Practical English] Ngữ pháp tiếng Anh từ A-Z","[Practical English] Học phát âm và thực hành giao tiếp tiếng Anh"]','images/catalog/study4/series-1.webp',2097000,1050000,NULL,'online',1,0,'2026-10-22 09:50:59',1,365,'2026-10-22 09:50:59','2026-10-22 09:50:59' FROM learning_categories cat WHERE cat.slug='catalog-combo' ON DUPLICATE KEY UPDATE `id`=`courses`.`id`;
INSERT INTO `learning_categories` (`slug`,`name`,`is_active`,`created_at`,`updated_at`) VALUES ('catalog-combo','Combo đặc biệt',1,'2026-10-22 09:50:59','2026-10-22 09:50:59') ON DUPLICATE KEY UPDATE `id`=`learning_categories`.`id`;
INSERT INTO `courses` (`learning_category_id`,`code`,`catalog_key`,`slug`,`name`,`summary`,`description`,`audience`,`learning_outcomes`,`curriculum_outline`,`thumbnail_path`,`price`,`sale_price`,`intro_video_url`,`delivery_mode`,`is_active`,`is_for_sale`,`published_at`,`duration_hours`,`access_days`,`created_at`,`updated_at`) SELECT cat.id,'EC-CAT-SERIES-6','series-6','chuong-trinh-series-6','Combo HSK 1-3','Lộ trình tiếng Trung từ phần nhập môn HSK 1–2 đến nội dung HSK 3.','Lộ trình tiếng Trung từ phần nhập môn HSK 1–2 đến nội dung HSK 3.\n\nCách học\nBắt đầu bằng việc xác định mục tiêu, đọc các chủ đề trong chương trình và chia thời gian học thành những buổi ngắn. Sau mỗi buổi, ghi lại kiến thức mới, tự giải thích bằng ví dụ của bản thân và ôn lại nội dung còn chưa chắc.\n\nHọc và luyện tập\nCác bài học được công bố sẽ xuất hiện trong chương trình học bên dưới. Khi khóa học được mở bán, bạn thêm vào giỏ, xác nhận thanh toán mô phỏng và truy cập từ mục Khóa học của tôi. Bài học và tiến độ được quản lý ngay trên English Center.','Người muốn kết hợp nhiều kỹ năng trong một lộ trình, học từ nền tảng đến thực hành theo từng chủ đề.','["Kết hợp nhiều kỹ năng trong một kế hoạch học thống nhất.","Củng cố nền tảng trước khi chuyển sang các chủ đề nâng cao.","Phân bổ thời gian học, ôn tập và tự đánh giá theo từng giai đoạn."]','["HSK 1+2 - Tiếng Trung cơ bản","Chinh phục HSK 3"]','images/catalog/study4/series-6.webp',1978000,1050000,'https://youtu.be/DG9cejvxlqc','online',1,0,'2026-10-22 09:50:59',1,365,'2026-10-22 09:50:59','2026-10-22 09:50:59' FROM learning_categories cat WHERE cat.slug='catalog-combo' ON DUPLICATE KEY UPDATE `id`=`courses`.`id`;
INSERT INTO `learning_categories` (`slug`,`name`,`is_active`,`created_at`,`updated_at`) VALUES ('catalog-toeic','TOEIC',1,'2026-10-22 09:50:59','2026-10-22 09:50:59') ON DUPLICATE KEY UPDATE `id`=`learning_categories`.`id`;
INSERT INTO `courses` (`learning_category_id`,`code`,`catalog_key`,`slug`,`name`,`summary`,`description`,`audience`,`learning_outcomes`,`curriculum_outline`,`thumbnail_path`,`price`,`sale_price`,`intro_video_url`,`delivery_mode`,`is_active`,`is_for_sale`,`published_at`,`duration_hours`,`access_days`,`created_at`,`updated_at`) SELECT cat.id,'EC-CAT-COURSE-28','course-28','chuong-trinh-course-28','[Complete TOEIC] Chiến lược làm bài - Từ vựng - Ngữ pháp - Luyện nghe với Dictation','Ôn TOEIC nghe và đọc theo từng phần thi, kết hợp từ vựng, ngữ pháp và luyện nghe chép chính tả.','Ôn TOEIC nghe và đọc theo từng phần thi, kết hợp từ vựng, ngữ pháp và luyện nghe chép chính tả.\n\nCách học\nBắt đầu bằng việc xác định mục tiêu, đọc các chủ đề trong chương trình và chia thời gian học thành những buổi ngắn. Sau mỗi buổi, ghi lại kiến thức mới, tự giải thích bằng ví dụ của bản thân và ôn lại nội dung còn chưa chắc.\n\nHọc và luyện tập\nCác bài học được công bố sẽ xuất hiện trong chương trình học bên dưới. Khi khóa học được mở bán, bạn thêm vào giỏ, xác nhận thanh toán mô phỏng và truy cập từ mục Khóa học của tôi. Bài học và tiến độ được quản lý ngay trên English Center.','Người đang chuẩn bị thi TOEIC, muốn xây dựng phương pháp học theo từng kỹ năng và luyện tập có mục tiêu.','["Nhận diện yêu cầu của từng phần thi TOEIC Listening và Reading.","Củng cố từ vựng, ngữ pháp và cách đọc thông tin trong bối cảnh công việc.","Tìm hiểu cách luyện nghe chép chính tả và phân tích lỗi sau khi luyện đề."]','["Từ vựng TOEIC","Ngữ pháp TOEIC","Part 1: Photographs - Nghe tranh","Part 2: Question - Response - Hỏi - đáp","Part 3: Conversations - Nghe hiểu đối thoại","Part 4: Talks - Nghe hiểu bài nói","Part 5: Incomplete Sentences - Điền từ vào câu","Part 6: Text Completion - Điền từ vào đoạn văn","Part 7: Reading Comprehension - Đọc hiểu văn bản","Luyện nghe chép chính tả TOEIC"]','images/catalog/study4/course-28.webp',1800000,1050000,'https://youtu.be/QV-X5DpteLk','online',1,0,'2026-10-22 09:50:59',1,365,'2026-10-22 09:50:59','2026-10-22 09:50:59' FROM learning_categories cat WHERE cat.slug='catalog-toeic' ON DUPLICATE KEY UPDATE `id`=`courses`.`id`;
INSERT INTO `learning_categories` (`slug`,`name`,`is_active`,`created_at`,`updated_at`) VALUES ('catalog-toeic','TOEIC',1,'2026-10-22 09:50:59','2026-10-22 09:50:59') ON DUPLICATE KEY UPDATE `id`=`learning_categories`.`id`;
INSERT INTO `courses` (`learning_category_id`,`code`,`catalog_key`,`slug`,`name`,`summary`,`description`,`audience`,`learning_outcomes`,`curriculum_outline`,`thumbnail_path`,`price`,`sale_price`,`intro_video_url`,`delivery_mode`,`is_active`,`is_for_sale`,`published_at`,`duration_hours`,`access_days`,`created_at`,`updated_at`) SELECT cat.id,'EC-CAT-COURSE-36','course-36','chuong-trinh-course-36','[TOEIC SW] TOEIC Speaking and Writing','Làm quen yêu cầu bài nói và bài viết TOEIC qua hướng dẫn dạng bài và hoạt động thực hành.','Làm quen yêu cầu bài nói và bài viết TOEIC qua hướng dẫn dạng bài và hoạt động thực hành.\n\nCách học\nBắt đầu bằng việc xác định mục tiêu, đọc các chủ đề trong chương trình và chia thời gian học thành những buổi ngắn. Sau mỗi buổi, ghi lại kiến thức mới, tự giải thích bằng ví dụ của bản thân và ôn lại nội dung còn chưa chắc.\n\nHọc và luyện tập\nCác bài học được công bố sẽ xuất hiện trong chương trình học bên dưới. Khi khóa học được mở bán, bạn thêm vào giỏ, xác nhận thanh toán mô phỏng và truy cập từ mục Khóa học của tôi. Bài học và tiến độ được quản lý ngay trên English Center.','Người đang chuẩn bị thi TOEIC, muốn xây dựng phương pháp học theo từng kỹ năng và luyện tập có mục tiêu.','["Tìm hiểu cấu trúc phần thi TOEIC Speaking và Writing.","Xây dựng câu trả lời cho phần mô tả tranh, phản hồi câu hỏi và trình bày quan điểm.","Thực hành lập ý cho email và bài viết nêu ý kiến."]','["Tổng quan TOEIC Speaking & Writing","[Speaking] Questions 1-2: Read a text aloud","[Speaking] Questions 3-4: Describe a picture","[Speaking] Questions 5-7: Respond to questions","[Speaking] Questions 8-10: Respond to questions using information provided","[Speaking] Question 11: Express an opinion","[Writing] Questions 1-5: Describe a picture","[Writing] Questions 6-7: Respond to an email","[Writing] Question 8: Write an opinion essay","PRACTICE ZONE"]','images/catalog/study4/course-36.webp',1800000,1050000,NULL,'online',1,0,'2026-10-22 09:50:59',1,365,'2026-10-22 09:50:59','2026-10-22 09:50:59' FROM learning_categories cat WHERE cat.slug='catalog-toeic' ON DUPLICATE KEY UPDATE `id`=`courses`.`id`;
INSERT INTO `learning_categories` (`slug`,`name`,`is_active`,`created_at`,`updated_at`) VALUES ('catalog-ielts-academic','IELTS Academic',1,'2026-10-22 09:50:59','2026-10-22 09:50:59') ON DUPLICATE KEY UPDATE `id`=`learning_categories`.`id`;
INSERT INTO `courses` (`learning_category_id`,`code`,`catalog_key`,`slug`,`name`,`summary`,`description`,`audience`,`learning_outcomes`,`curriculum_outline`,`thumbnail_path`,`price`,`sale_price`,`intro_video_url`,`delivery_mode`,`is_active`,`is_for_sale`,`published_at`,`duration_hours`,`access_days`,`created_at`,`updated_at`) SELECT cat.id,'EC-CAT-COURSE-26','course-26','chuong-trinh-course-26','[IELTS Fundamentals] Từ vựng và ngữ pháp cơ bản IELTS','Củng cố từ vựng và ngữ pháp nền tảng trước khi luyện sâu các kỹ năng IELTS.','Củng cố từ vựng và ngữ pháp nền tảng trước khi luyện sâu các kỹ năng IELTS.\n\nCách học\nBắt đầu bằng việc xác định mục tiêu, đọc các chủ đề trong chương trình và chia thời gian học thành những buổi ngắn. Sau mỗi buổi, ghi lại kiến thức mới, tự giải thích bằng ví dụ của bản thân và ôn lại nội dung còn chưa chắc.\n\nHọc và luyện tập\nCác bài học được công bố sẽ xuất hiện trong chương trình học bên dưới. Khi khóa học được mở bán, bạn thêm vào giỏ, xác nhận thanh toán mô phỏng và truy cập từ mục Khóa học của tôi. Bài học và tiến độ được quản lý ngay trên English Center.','Người học IELTS Academic muốn củng cố kiến thức và tìm hiểu các dạng bài trước khi xây dựng lộ trình luyện thi.','["Hệ thống từ vựng theo các chủ đề thường gặp trong IELTS.","Phân biệt từ loại, các thì và cấu trúc mệnh đề trong câu tiếng Anh.","Vận dụng ngữ pháp nền tảng khi đọc hiểu và xây dựng câu viết."]','["[Vocabulary] Từ vựng theo chủ đề","[Grammar] Parts of speech - Từ loại","[Grammar] Tenses - Thì","[Grammar] Clauses - Mệnh đề","[Grammar] in Writing - Văn viết"]','images/catalog/study4/course-26.webp',989000,799000,'https://youtu.be/fAstAgLJCsU','online',1,0,'2026-10-22 09:50:59',1,365,'2026-10-22 09:50:59','2026-10-22 09:50:59' FROM learning_categories cat WHERE cat.slug='catalog-ielts-academic' ON DUPLICATE KEY UPDATE `id`=`courses`.`id`;
INSERT INTO `learning_categories` (`slug`,`name`,`is_active`,`created_at`,`updated_at`) VALUES ('catalog-ielts-academic','IELTS Academic',1,'2026-10-22 09:50:59','2026-10-22 09:50:59') ON DUPLICATE KEY UPDATE `id`=`learning_categories`.`id`;
INSERT INTO `courses` (`learning_category_id`,`code`,`catalog_key`,`slug`,`name`,`summary`,`description`,`audience`,`learning_outcomes`,`curriculum_outline`,`thumbnail_path`,`price`,`sale_price`,`intro_video_url`,`delivery_mode`,`is_active`,`is_for_sale`,`published_at`,`duration_hours`,`access_days`,`created_at`,`updated_at`) SELECT cat.id,'EC-CAT-COURSE-15','course-15','chuong-trinh-course-15','[IELTS Intensive Listening] Chiến lược làm bài - Chữa đề - Luyện nghe IELTS Listening theo phương pháp Dictation','Luyện nghe IELTS theo dạng câu hỏi, kết hợp nghe chép chính tả, ôn từ vựng và chữa đề.','Luyện nghe IELTS theo dạng câu hỏi, kết hợp nghe chép chính tả, ôn từ vựng và chữa đề.\n\nCách học\nBắt đầu bằng việc xác định mục tiêu, đọc các chủ đề trong chương trình và chia thời gian học thành những buổi ngắn. Sau mỗi buổi, ghi lại kiến thức mới, tự giải thích bằng ví dụ của bản thân và ôn lại nội dung còn chưa chắc.\n\nHọc và luyện tập\nCác bài học được công bố sẽ xuất hiện trong chương trình học bên dưới. Khi khóa học được mở bán, bạn thêm vào giỏ, xác nhận thanh toán mô phỏng và truy cập từ mục Khóa học của tôi. Bài học và tiến độ được quản lý ngay trên English Center.','Người học IELTS Academic muốn củng cố kiến thức và tìm hiểu các dạng bài trước khi xây dựng lộ trình luyện thi.','["Nhận diện các dạng câu hỏi và cách xác định từ khóa trong IELTS Listening.","Rèn nghe chi tiết, phân biệt âm nối và kiểm tra chính tả khi điền đáp án.","Tổ chức việc luyện nghe chép chính tả theo từ vựng, chủ đề và đoạn hội thoại."]','["Bài học thử","Hướng dẫn làm các dạng câu hỏi trong IELTS Listening","Luyện nghe chính tả từ vựng","Luyện nghe chính tả theo chủ đề (cơ bản - nâng cao)","Luyện nghe chính tả đề IELTS","PRACTICE ZONE","Chữa đề IELTS chi tiết","Tổng hợp từ vựng theo chủ đề"]','images/catalog/study4/course-15.webp',989000,799000,'https://youtu.be/__nzODTNbjM','online',1,0,'2026-10-22 09:50:59',1,365,'2026-10-22 09:50:59','2026-10-22 09:50:59' FROM learning_categories cat WHERE cat.slug='catalog-ielts-academic' ON DUPLICATE KEY UPDATE `id`=`courses`.`id`;
INSERT INTO `learning_categories` (`slug`,`name`,`is_active`,`created_at`,`updated_at`) VALUES ('catalog-ielts-academic','IELTS Academic',1,'2026-10-22 09:50:59','2026-10-22 09:50:59') ON DUPLICATE KEY UPDATE `id`=`learning_categories`.`id`;
INSERT INTO `courses` (`learning_category_id`,`code`,`catalog_key`,`slug`,`name`,`summary`,`description`,`audience`,`learning_outcomes`,`curriculum_outline`,`thumbnail_path`,`price`,`sale_price`,`intro_video_url`,`delivery_mode`,`is_active`,`is_for_sale`,`published_at`,`duration_hours`,`access_days`,`created_at`,`updated_at`) SELECT cat.id,'EC-CAT-COURSE-22','course-22','chuong-trinh-course-22','[IELTS Intensive Reading] Chiến lược làm bài - Chữa đề - Từ vựng IELTS Reading','Rèn kỹ năng đọc IELTS qua hướng dẫn dạng câu hỏi, phân tích đề và học từ vựng.','Rèn kỹ năng đọc IELTS qua hướng dẫn dạng câu hỏi, phân tích đề và học từ vựng.\n\nCách học\nBắt đầu bằng việc xác định mục tiêu, đọc các chủ đề trong chương trình và chia thời gian học thành những buổi ngắn. Sau mỗi buổi, ghi lại kiến thức mới, tự giải thích bằng ví dụ của bản thân và ôn lại nội dung còn chưa chắc.\n\nHọc và luyện tập\nCác bài học được công bố sẽ xuất hiện trong chương trình học bên dưới. Khi khóa học được mở bán, bạn thêm vào giỏ, xác nhận thanh toán mô phỏng và truy cập từ mục Khóa học của tôi. Bài học và tiến độ được quản lý ngay trên English Center.','Người học IELTS Academic muốn củng cố kiến thức và tìm hiểu các dạng bài trước khi xây dựng lộ trình luyện thi.','["Kết hợp đọc lướt để tìm ý chính và đọc quét để xác định thông tin.","Phân tích từ khóa, từ đồng nghĩa và bằng chứng trong đoạn đọc.","Nhận diện yêu cầu của các dạng câu hỏi đọc hiểu và kiểm tra lại đáp án."]','["Bài học thử","Phương pháp làm các dạng câu hỏi trong IELTS Reading","Từ vựng IELTS Academic Reading","PRACTICE ZONE","Chữa đề IELTS chi tiết","Tổng hợp từ vựng theo chủ đề"]','images/catalog/study4/course-22.webp',989000,799000,'https://youtu.be/Bjb5i-tfAMk','online',1,0,'2026-10-22 09:50:59',1,365,'2026-10-22 09:50:59','2026-10-22 09:50:59' FROM learning_categories cat WHERE cat.slug='catalog-ielts-academic' ON DUPLICATE KEY UPDATE `id`=`courses`.`id`;
INSERT INTO `learning_categories` (`slug`,`name`,`is_active`,`created_at`,`updated_at`) VALUES ('catalog-ielts-academic','IELTS Academic',1,'2026-10-22 09:50:59','2026-10-22 09:50:59') ON DUPLICATE KEY UPDATE `id`=`learning_categories`.`id`;
INSERT INTO `courses` (`learning_category_id`,`code`,`catalog_key`,`slug`,`name`,`summary`,`description`,`audience`,`learning_outcomes`,`curriculum_outline`,`thumbnail_path`,`price`,`sale_price`,`intro_video_url`,`delivery_mode`,`is_active`,`is_for_sale`,`published_at`,`duration_hours`,`access_days`,`created_at`,`updated_at`) SELECT cat.id,'EC-CAT-COURSE-27','course-27','chuong-trinh-course-27','[IELTS Intensive Speaking] Thực hành luyện tập IELTS Speaking','Thực hành phần thi nói IELTS, kết hợp cách xây dựng câu trả lời và luyện phát âm.','Thực hành phần thi nói IELTS, kết hợp cách xây dựng câu trả lời và luyện phát âm.\n\nCách học\nBắt đầu bằng việc xác định mục tiêu, đọc các chủ đề trong chương trình và chia thời gian học thành những buổi ngắn. Sau mỗi buổi, ghi lại kiến thức mới, tự giải thích bằng ví dụ của bản thân và ôn lại nội dung còn chưa chắc.\n\nHọc và luyện tập\nCác bài học được công bố sẽ xuất hiện trong chương trình học bên dưới. Khi khóa học được mở bán, bạn thêm vào giỏ, xác nhận thanh toán mô phỏng và truy cập từ mục Khóa học của tôi. Bài học và tiến độ được quản lý ngay trên English Center.','Người học IELTS Academic muốn củng cố kiến thức và tìm hiểu các dạng bài trước khi xây dựng lộ trình luyện thi.','["Củng cố phát âm, trọng âm, nhịp điệu và cách nối âm.","Tổ chức ý tưởng cho câu trả lời ở từng phần thi IELTS Speaking.","Xây dựng thói quen tự ghi âm, nghe lại và cải thiện cách diễn đạt."]','["Nguyên âm (Vowels) và phụ âm (Consonants)","Trọng âm (Stress)","Nhịp điệu (Rhythm) và cụm từ diễn tả ý tưởng (Thought groups)","Ngữ điệu (Intonation)","Liên kết (Linking) và nối âm (Connected speech)","Hướng dẫn làm bài IELTS Speaking Test","Part 1 topics","Part 2+3 topics","PRACTICE ZONE"]','images/catalog/study4/course-27.webp',989000,799000,'https://youtu.be/aY4SkdYwRt8','online',1,0,'2026-10-22 09:50:59',1,365,'2026-10-22 09:50:59','2026-10-22 09:50:59' FROM learning_categories cat WHERE cat.slug='catalog-ielts-academic' ON DUPLICATE KEY UPDATE `id`=`courses`.`id`;
INSERT INTO `learning_categories` (`slug`,`name`,`is_active`,`created_at`,`updated_at`) VALUES ('catalog-ielts-academic','IELTS Academic',1,'2026-10-22 09:50:59','2026-10-22 09:50:59') ON DUPLICATE KEY UPDATE `id`=`learning_categories`.`id`;
INSERT INTO `courses` (`learning_category_id`,`code`,`catalog_key`,`slug`,`name`,`summary`,`description`,`audience`,`learning_outcomes`,`curriculum_outline`,`thumbnail_path`,`price`,`sale_price`,`intro_video_url`,`delivery_mode`,`is_active`,`is_for_sale`,`published_at`,`duration_hours`,`access_days`,`created_at`,`updated_at`) SELECT cat.id,'EC-CAT-COURSE-25','course-25','chuong-trinh-course-25','[IELTS Intensive Writing] Thực hành luyện tập IELTS Writing','Tìm hiểu cách triển khai bài viết IELTS và luyện tập theo các dạng đề.','Tìm hiểu cách triển khai bài viết IELTS và luyện tập theo các dạng đề.\n\nCách học\nBắt đầu bằng việc xác định mục tiêu, đọc các chủ đề trong chương trình và chia thời gian học thành những buổi ngắn. Sau mỗi buổi, ghi lại kiến thức mới, tự giải thích bằng ví dụ của bản thân và ôn lại nội dung còn chưa chắc.\n\nHọc và luyện tập\nCác bài học được công bố sẽ xuất hiện trong chương trình học bên dưới. Khi khóa học được mở bán, bạn thêm vào giỏ, xác nhận thanh toán mô phỏng và truy cập từ mục Khóa học của tôi. Bài học và tiến độ được quản lý ngay trên English Center.','Người học IELTS Academic muốn củng cố kiến thức và tìm hiểu các dạng bài trước khi xây dựng lộ trình luyện thi.','["Tìm hiểu cách tiếp cận đề bài IELTS Writing Task 1 và Task 2.","Lập dàn ý, tổ chức đoạn văn và phát triển luận điểm có dẫn chứng.","Tự kiểm tra ngữ pháp, từ vựng và tính liên kết sau khi viết."]','["Hướng dẫn làm Task 1","Hướng dẫn làm Task 2","TASK 1: Các dạng câu hỏi","TASK 2: Các dạng câu hỏi","TASK 2: Chủ đề thường gặp","PRACTICE ZONE"]','images/catalog/study4/course-25.webp',989000,799000,'https://youtu.be/_g5DYZApjYc','online',1,0,'2026-10-22 09:50:59',1,365,'2026-10-22 09:50:59','2026-10-22 09:50:59' FROM learning_categories cat WHERE cat.slug='catalog-ielts-academic' ON DUPLICATE KEY UPDATE `id`=`courses`.`id`;
INSERT INTO `learning_categories` (`slug`,`name`,`is_active`,`created_at`,`updated_at`) VALUES ('catalog-ielts-general','IELTS General',1,'2026-10-22 09:50:59','2026-10-22 09:50:59') ON DUPLICATE KEY UPDATE `id`=`learning_categories`.`id`;
INSERT INTO `courses` (`learning_category_id`,`code`,`catalog_key`,`slug`,`name`,`summary`,`description`,`audience`,`learning_outcomes`,`curriculum_outline`,`thumbnail_path`,`price`,`sale_price`,`intro_video_url`,`delivery_mode`,`is_active`,`is_for_sale`,`published_at`,`duration_hours`,`access_days`,`created_at`,`updated_at`) SELECT cat.id,'EC-CAT-COURSE-29','course-29','chuong-trinh-course-29','[IELTS General Training] Intensive Reading: Từ Vựng - Chiến Lược Làm Bài - Chữa đề chi tiết','Tập trung kỹ năng đọc của IELTS General Training với từ vựng, dạng bài và phần giải thích đề.','Tập trung kỹ năng đọc của IELTS General Training với từ vựng, dạng bài và phần giải thích đề.\n\nCách học\nBắt đầu bằng việc xác định mục tiêu, đọc các chủ đề trong chương trình và chia thời gian học thành những buổi ngắn. Sau mỗi buổi, ghi lại kiến thức mới, tự giải thích bằng ví dụ của bản thân và ôn lại nội dung còn chưa chắc.\n\nHọc và luyện tập\nCác bài học được công bố sẽ xuất hiện trong chương trình học bên dưới. Khi khóa học được mở bán, bạn thêm vào giỏ, xác nhận thanh toán mô phỏng và truy cập từ mục Khóa học của tôi. Bài học và tiến độ được quản lý ngay trên English Center.','Người chuẩn bị IELTS General Training cho công việc, học tập hoặc cuộc sống tại môi trường sử dụng tiếng Anh.','["Kết hợp đọc lướt để tìm ý chính và đọc quét để xác định thông tin.","Phân tích từ khóa, từ đồng nghĩa và bằng chứng trong đoạn đọc.","Nhận diện yêu cầu của các dạng câu hỏi đọc hiểu và kiểm tra lại đáp án."]','["Bài học thử","Phương pháp làm các dạng câu hỏi trong IELTS General Reading","Từ vựng IELTS GT Reading","PRACTICE ZONE","Chữa đề IELTS chi tiết"]','images/catalog/study4/course-29.webp',989000,799000,'https://youtu.be/XAsOYTDA3A8','online',1,0,'2026-10-22 09:50:59',1,365,'2026-10-22 09:50:59','2026-10-22 09:50:59' FROM learning_categories cat WHERE cat.slug='catalog-ielts-general' ON DUPLICATE KEY UPDATE `id`=`courses`.`id`;
INSERT INTO `learning_categories` (`slug`,`name`,`is_active`,`created_at`,`updated_at`) VALUES ('catalog-ielts-general','IELTS General',1,'2026-10-22 09:50:59','2026-10-22 09:50:59') ON DUPLICATE KEY UPDATE `id`=`learning_categories`.`id`;
INSERT INTO `courses` (`learning_category_id`,`code`,`catalog_key`,`slug`,`name`,`summary`,`description`,`audience`,`learning_outcomes`,`curriculum_outline`,`thumbnail_path`,`price`,`sale_price`,`intro_video_url`,`delivery_mode`,`is_active`,`is_for_sale`,`published_at`,`duration_hours`,`access_days`,`created_at`,`updated_at`) SELECT cat.id,'EC-CAT-COURSE-30','course-30','chuong-trinh-course-30','[IELTS General Training] Intensive Writing: Thực hành luyện tập Writing GT','Thực hành viết thư và bài luận theo yêu cầu của IELTS General Training.','Thực hành viết thư và bài luận theo yêu cầu của IELTS General Training.\n\nCách học\nBắt đầu bằng việc xác định mục tiêu, đọc các chủ đề trong chương trình và chia thời gian học thành những buổi ngắn. Sau mỗi buổi, ghi lại kiến thức mới, tự giải thích bằng ví dụ của bản thân và ôn lại nội dung còn chưa chắc.\n\nHọc và luyện tập\nCác bài học được công bố sẽ xuất hiện trong chương trình học bên dưới. Khi khóa học được mở bán, bạn thêm vào giỏ, xác nhận thanh toán mô phỏng và truy cập từ mục Khóa học của tôi. Bài học và tiến độ được quản lý ngay trên English Center.','Người chuẩn bị IELTS General Training cho công việc, học tập hoặc cuộc sống tại môi trường sử dụng tiếng Anh.','["Nhận diện mục đích và cách xưng hô trong thư IELTS General Training.","Lập ý cho thư và bài luận theo yêu cầu từng dạng đề.","Kiểm tra độ đầy đủ của ý, cấu trúc đoạn và cách sử dụng từ."]','["Bài học thử","Hướng dẫn làm Task 1","Hướng dẫn làm Task 2","TASK 1: Các dạng câu hỏi","TASK 2: Các dạng câu hỏi","TASK 2: Chủ đề thường gặp","PRACTICE ZONE"]','images/catalog/study4/course-30.webp',989000,799000,'https://youtu.be/oyeqBYuVWfo','online',1,0,'2026-10-22 09:50:59',1,365,'2026-10-22 09:50:59','2026-10-22 09:50:59' FROM learning_categories cat WHERE cat.slug='catalog-ielts-general' ON DUPLICATE KEY UPDATE `id`=`courses`.`id`;
INSERT INTO `learning_categories` (`slug`,`name`,`is_active`,`created_at`,`updated_at`) VALUES ('catalog-english-foundation','Tiếng Anh cơ bản',1,'2026-10-22 09:50:59','2026-10-22 09:50:59') ON DUPLICATE KEY UPDATE `id`=`learning_categories`.`id`;
INSERT INTO `courses` (`learning_category_id`,`code`,`catalog_key`,`slug`,`name`,`summary`,`description`,`audience`,`learning_outcomes`,`curriculum_outline`,`thumbnail_path`,`price`,`sale_price`,`intro_video_url`,`delivery_mode`,`is_active`,`is_for_sale`,`published_at`,`duration_hours`,`access_days`,`created_at`,`updated_at`) SELECT cat.id,'EC-CAT-COURSE-16','course-16','chuong-trinh-course-16','[Practical English] Luyện nghe nói tiếng Anh cùng TED Talks','Luyện nghe và nói với các nội dung TED Talks được giới thiệu trong chương trình.','Luyện nghe và nói với các nội dung TED Talks được giới thiệu trong chương trình.\n\nCách học\nBắt đầu bằng việc xác định mục tiêu, đọc các chủ đề trong chương trình và chia thời gian học thành những buổi ngắn. Sau mỗi buổi, ghi lại kiến thức mới, tự giải thích bằng ví dụ của bản thân và ôn lại nội dung còn chưa chắc.\n\nHọc và luyện tập\nCác bài học được công bố sẽ xuất hiện trong chương trình học bên dưới. Khi khóa học được mở bán, bạn thêm vào giỏ, xác nhận thanh toán mô phỏng và truy cập từ mục Khóa học của tôi. Bài học và tiến độ được quản lý ngay trên English Center.','Người muốn củng cố tiếng Anh nền tảng, hình thành thói quen học đều và ứng dụng kiến thức trong giao tiếp hằng ngày.','["Luyện nghe ý chính và ghi chú thông tin trong bài nói.","Tìm hiểu cách diễn đạt, từ vựng và thông điệp theo chủ đề.","Tập kể lại nội dung và trình bày quan điểm bằng tiếng Anh."]','["TED - Short videos (0-6 min)","TED - Long videos (6+ min)"]','images/catalog/study4/course-16.webp',699000,599000,NULL,'online',1,0,'2026-10-22 09:50:59',1,365,'2026-10-22 09:50:59','2026-10-22 09:50:59' FROM learning_categories cat WHERE cat.slug='catalog-english-foundation' ON DUPLICATE KEY UPDATE `id`=`courses`.`id`;
INSERT INTO `learning_categories` (`slug`,`name`,`is_active`,`created_at`,`updated_at`) VALUES ('catalog-english-foundation','Tiếng Anh cơ bản',1,'2026-10-22 09:50:59','2026-10-22 09:50:59') ON DUPLICATE KEY UPDATE `id`=`learning_categories`.`id`;
INSERT INTO `courses` (`learning_category_id`,`code`,`catalog_key`,`slug`,`name`,`summary`,`description`,`audience`,`learning_outcomes`,`curriculum_outline`,`thumbnail_path`,`price`,`sale_price`,`intro_video_url`,`delivery_mode`,`is_active`,`is_for_sale`,`published_at`,`duration_hours`,`access_days`,`created_at`,`updated_at`) SELECT cat.id,'EC-CAT-COURSE-12','course-12','chuong-trinh-course-12','[Practical English] 3600 từ vựng tiếng Anh thông dụng','Học nhóm từ vựng tiếng Anh thông dụng, kết hợp nhận diện nghĩa và ôn tập.','Học nhóm từ vựng tiếng Anh thông dụng, kết hợp nhận diện nghĩa và ôn tập.\n\nCách học\nBắt đầu bằng việc xác định mục tiêu, đọc các chủ đề trong chương trình và chia thời gian học thành những buổi ngắn. Sau mỗi buổi, ghi lại kiến thức mới, tự giải thích bằng ví dụ của bản thân và ôn lại nội dung còn chưa chắc.\n\nHọc và luyện tập\nCác bài học được công bố sẽ xuất hiện trong chương trình học bên dưới. Khi khóa học được mở bán, bạn thêm vào giỏ, xác nhận thanh toán mô phỏng và truy cập từ mục Khóa học của tôi. Bài học và tiến độ được quản lý ngay trên English Center.','Người muốn củng cố tiếng Anh nền tảng, hình thành thói quen học đều và ứng dụng kiến thức trong giao tiếp hằng ngày.','["Sắp xếp từ vựng thành nhóm theo chủ đề và tình huống sử dụng.","Học nghĩa, cách kết hợp từ và tự đặt câu minh họa.","Xây dựng lịch ôn lại từ mới để tăng khả năng ghi nhớ."]','["Basic words (Từ vựng cơ bản)","Pronouns (Đại từ)","General verbs (Động từ cơ bản)","Adjectives (Tính từ)","Adverb (Trạng từ)","Phrasal verbs (Cụm động từ)","People (Mọi người)","Thematic verbs (Động từ chuyên đề)","From the life (Cuộc sống)","School, work, money (Trường học, công việc, tiền bạc)","Food (Món ăn)","Travel (Du lịch)"]','images/catalog/study4/course-12.webp',699000,599000,NULL,'online',1,0,'2026-10-22 09:50:59',1,365,'2026-10-22 09:50:59','2026-10-22 09:50:59' FROM learning_categories cat WHERE cat.slug='catalog-english-foundation' ON DUPLICATE KEY UPDATE `id`=`courses`.`id`;
INSERT INTO `learning_categories` (`slug`,`name`,`is_active`,`created_at`,`updated_at`) VALUES ('catalog-english-foundation','Tiếng Anh cơ bản',1,'2026-10-22 09:50:59','2026-10-22 09:50:59') ON DUPLICATE KEY UPDATE `id`=`learning_categories`.`id`;
INSERT INTO `courses` (`learning_category_id`,`code`,`catalog_key`,`slug`,`name`,`summary`,`description`,`audience`,`learning_outcomes`,`curriculum_outline`,`thumbnail_path`,`price`,`sale_price`,`intro_video_url`,`delivery_mode`,`is_active`,`is_for_sale`,`published_at`,`duration_hours`,`access_days`,`created_at`,`updated_at`) SELECT cat.id,'EC-CAT-COURSE-13','course-13','chuong-trinh-course-13','[Practical English] Ngữ pháp tiếng Anh từ A-Z','Ôn các chủ điểm ngữ pháp tiếng Anh theo một chương trình có hệ thống.','Ôn các chủ điểm ngữ pháp tiếng Anh theo một chương trình có hệ thống.\n\nCách học\nBắt đầu bằng việc xác định mục tiêu, đọc các chủ đề trong chương trình và chia thời gian học thành những buổi ngắn. Sau mỗi buổi, ghi lại kiến thức mới, tự giải thích bằng ví dụ của bản thân và ôn lại nội dung còn chưa chắc.\n\nHọc và luyện tập\nCác bài học được công bố sẽ xuất hiện trong chương trình học bên dưới. Khi khóa học được mở bán, bạn thêm vào giỏ, xác nhận thanh toán mô phỏng và truy cập từ mục Khóa học của tôi. Bài học và tiến độ được quản lý ngay trên English Center.','Người muốn củng cố tiếng Anh nền tảng, hình thành thói quen học đều và ứng dụng kiến thức trong giao tiếp hằng ngày.','["Phân biệt các thì và chọn cấu trúc phù hợp với ngữ cảnh.","Củng cố từ loại, mạo từ, giới từ và động từ khuyết thiếu.","Phát hiện lỗi thường gặp và tự giải thích cách sửa câu."]','["Talking about the present (Nói về hiện tại)","Talking about the past (Nói về quá khứ)","Talking about the future (Nói về tương lai)","To be, to have, to do (là / có / làm)","Tenses: mix (Các thì: Tổng hợp)","Parts of speech (Từ loại)","Plurals (Số nhiều)","Articles (Mạo từ)","Prepositions (Giới từ)","Modal verbs (Động từ khuyết thiếu)","Pronouns (Đại từ)","Adjectives and adverbs (Tính từ và trạng từ)"]','images/catalog/study4/course-13.webp',699000,599000,NULL,'online',1,0,'2026-10-22 09:50:59',1,365,'2026-10-22 09:50:59','2026-10-22 09:50:59' FROM learning_categories cat WHERE cat.slug='catalog-english-foundation' ON DUPLICATE KEY UPDATE `id`=`courses`.`id`;
INSERT INTO `learning_categories` (`slug`,`name`,`is_active`,`created_at`,`updated_at`) VALUES ('catalog-english-foundation','Tiếng Anh cơ bản',1,'2026-10-22 09:50:59','2026-10-22 09:50:59') ON DUPLICATE KEY UPDATE `id`=`learning_categories`.`id`;
INSERT INTO `courses` (`learning_category_id`,`code`,`catalog_key`,`slug`,`name`,`summary`,`description`,`audience`,`learning_outcomes`,`curriculum_outline`,`thumbnail_path`,`price`,`sale_price`,`intro_video_url`,`delivery_mode`,`is_active`,`is_for_sale`,`published_at`,`duration_hours`,`access_days`,`created_at`,`updated_at`) SELECT cat.id,'EC-CAT-COURSE-14','course-14','chuong-trinh-course-14','[Practical English] Học phát âm và thực hành giao tiếp tiếng Anh','Luyện phát âm và thực hành giao tiếp với các tình huống trong chương trình.','Luyện phát âm và thực hành giao tiếp với các tình huống trong chương trình.\n\nCách học\nBắt đầu bằng việc xác định mục tiêu, đọc các chủ đề trong chương trình và chia thời gian học thành những buổi ngắn. Sau mỗi buổi, ghi lại kiến thức mới, tự giải thích bằng ví dụ của bản thân và ôn lại nội dung còn chưa chắc.\n\nHọc và luyện tập\nCác bài học được công bố sẽ xuất hiện trong chương trình học bên dưới. Khi khóa học được mở bán, bạn thêm vào giỏ, xác nhận thanh toán mô phỏng và truy cập từ mục Khóa học của tôi. Bài học và tiến độ được quản lý ngay trên English Center.','Người muốn củng cố tiếng Anh nền tảng, hình thành thói quen học đều và ứng dụng kiến thức trong giao tiếp hằng ngày.','["Nhận diện các âm cơ bản và luyện khẩu hình khi phát âm.","Tập sử dụng những cách diễn đạt phổ biến trong giao tiếp.","Luyện nói theo tình huống, chú ý nhịp điệu và độ rõ của lời nói."]','["Unit 1: Những âm cơ bản trong tiếng Anh","Unit 2: Các cách diễn đạt thông dụng trong giao tiếp tiếng Anh","Unit 3: Thực hành hội thoại tiếng Anh trình độ cơ bản","Unit 4: Thực hành 75 đoạn hội thoại theo chủ đề trình độ nâng cao"]','images/catalog/study4/course-14.webp',699000,599000,NULL,'online',1,0,'2026-10-22 09:50:59',1,365,'2026-10-22 09:50:59','2026-10-22 09:50:59' FROM learning_categories cat WHERE cat.slug='catalog-english-foundation' ON DUPLICATE KEY UPDATE `id`=`courses`.`id`;
INSERT INTO `learning_categories` (`slug`,`name`,`is_active`,`created_at`,`updated_at`) VALUES ('catalog-english-foundation','Tiếng Anh cơ bản',1,'2026-10-22 09:50:59','2026-10-22 09:50:59') ON DUPLICATE KEY UPDATE `id`=`learning_categories`.`id`;
INSERT INTO `courses` (`learning_category_id`,`code`,`catalog_key`,`slug`,`name`,`summary`,`description`,`audience`,`learning_outcomes`,`curriculum_outline`,`thumbnail_path`,`price`,`sale_price`,`intro_video_url`,`delivery_mode`,`is_active`,`is_for_sale`,`published_at`,`duration_hours`,`access_days`,`created_at`,`updated_at`) SELECT cat.id,'EC-CAT-COURSE-21','course-21','chuong-trinh-course-21','[Practical English] Học tiếng Anh qua bài hát','Khám phá từ vựng và cách diễn đạt tiếng Anh qua bài hát.','Khám phá từ vựng và cách diễn đạt tiếng Anh qua bài hát.\n\nCách học\nBắt đầu bằng việc xác định mục tiêu, đọc các chủ đề trong chương trình và chia thời gian học thành những buổi ngắn. Sau mỗi buổi, ghi lại kiến thức mới, tự giải thích bằng ví dụ của bản thân và ôn lại nội dung còn chưa chắc.\n\nHọc và luyện tập\nCác bài học được công bố sẽ xuất hiện trong chương trình học bên dưới. Khi khóa học được mở bán, bạn thêm vào giỏ, xác nhận thanh toán mô phỏng và truy cập từ mục Khóa học của tôi. Bài học và tiến độ được quản lý ngay trên English Center.','Người muốn củng cố tiếng Anh nền tảng, hình thành thói quen học đều và ứng dụng kiến thức trong giao tiếp hằng ngày.','["Nhận diện từ và cách diễn đạt trong ngữ cảnh bài hát.","Luyện nghe nối âm và nhịp điệu tiếng Anh.","Ôn lại từ vựng bằng câu ví dụ và các lần nghe lặp lại."]','["Music videos (Beginner)","Music videos (Intermediate)","Music videos (Advanced)"]','images/catalog/study4/course-21.webp',699000,599000,NULL,'online',1,0,'2026-10-22 09:50:59',1,365,'2026-10-22 09:50:59','2026-10-22 09:50:59' FROM learning_categories cat WHERE cat.slug='catalog-english-foundation' ON DUPLICATE KEY UPDATE `id`=`courses`.`id`;
INSERT INTO `learning_categories` (`slug`,`name`,`is_active`,`created_at`,`updated_at`) VALUES ('catalog-hsk','HSK',1,'2026-10-22 09:50:59','2026-10-22 09:50:59') ON DUPLICATE KEY UPDATE `id`=`learning_categories`.`id`;
INSERT INTO `courses` (`learning_category_id`,`code`,`catalog_key`,`slug`,`name`,`summary`,`description`,`audience`,`learning_outcomes`,`curriculum_outline`,`thumbnail_path`,`price`,`sale_price`,`intro_video_url`,`delivery_mode`,`is_active`,`is_for_sale`,`published_at`,`duration_hours`,`access_days`,`created_at`,`updated_at`) SELECT cat.id,'EC-CAT-COURSE-31','course-31','chuong-trinh-course-31','HSK 1+2 - Tiếng Trung cơ bản','Khởi đầu học tiếng Trung với nội dung căn bản của HSK 1 và HSK 2.','Khởi đầu học tiếng Trung với nội dung căn bản của HSK 1 và HSK 2.\n\nCách học\nBắt đầu bằng việc xác định mục tiêu, đọc các chủ đề trong chương trình và chia thời gian học thành những buổi ngắn. Sau mỗi buổi, ghi lại kiến thức mới, tự giải thích bằng ví dụ của bản thân và ôn lại nội dung còn chưa chắc.\n\nHọc và luyện tập\nCác bài học được công bố sẽ xuất hiện trong chương trình học bên dưới. Khi khóa học được mở bán, bạn thêm vào giỏ, xác nhận thanh toán mô phỏng và truy cập từ mục Khóa học của tôi. Bài học và tiến độ được quản lý ngay trên English Center.','Người học tiếng Trung muốn phát triển từ vựng, ngữ pháp và kỹ năng làm bài theo cấp độ HSK.','["Hệ thống từ vựng và ngữ pháp theo cấp độ HSK của chương trình.","Luyện nhận diện chữ Hán và áp dụng kiến thức trong câu.","Tìm hiểu cách tiếp cận các phần nghe, đọc và viết theo cấp độ."]','["Ngữ Âm","Chữ Hán","[HSK 1] Các chủ điểm","[HSK 1] Ngữ Pháp (cập nhật HSK 3.0)","[HSK 1] Luyện chép chính tả","[HSK 1] Từ vựng bổ sung New HSK 3.0","[HSK 2] Các chủ điểm","[HSK 2] Ngữ Pháp (cập nhật HSK 3.0)","[HSK 2] Luyện chép chính tả","[HSK 2] Từ vựng bổ sung New HSK 3.0","PRACTICE ZONE"]','images/catalog/study4/course-31.webp',989000,799000,'https://youtu.be/DG9cejvxlqc','online',1,0,'2026-10-22 09:50:59',1,365,'2026-10-22 09:50:59','2026-10-22 09:50:59' FROM learning_categories cat WHERE cat.slug='catalog-hsk' ON DUPLICATE KEY UPDATE `id`=`courses`.`id`;
INSERT INTO `learning_categories` (`slug`,`name`,`is_active`,`created_at`,`updated_at`) VALUES ('catalog-hsk','HSK',1,'2026-10-22 09:50:59','2026-10-22 09:50:59') ON DUPLICATE KEY UPDATE `id`=`learning_categories`.`id`;
INSERT INTO `courses` (`learning_category_id`,`code`,`catalog_key`,`slug`,`name`,`summary`,`description`,`audience`,`learning_outcomes`,`curriculum_outline`,`thumbnail_path`,`price`,`sale_price`,`intro_video_url`,`delivery_mode`,`is_active`,`is_for_sale`,`published_at`,`duration_hours`,`access_days`,`created_at`,`updated_at`) SELECT cat.id,'EC-CAT-COURSE-32','course-32','chuong-trinh-course-32','Chinh phục HSK 3','Ôn kiến thức và làm quen yêu cầu bài thi HSK 3.','Ôn kiến thức và làm quen yêu cầu bài thi HSK 3.\n\nCách học\nBắt đầu bằng việc xác định mục tiêu, đọc các chủ đề trong chương trình và chia thời gian học thành những buổi ngắn. Sau mỗi buổi, ghi lại kiến thức mới, tự giải thích bằng ví dụ của bản thân và ôn lại nội dung còn chưa chắc.\n\nHọc và luyện tập\nCác bài học được công bố sẽ xuất hiện trong chương trình học bên dưới. Khi khóa học được mở bán, bạn thêm vào giỏ, xác nhận thanh toán mô phỏng và truy cập từ mục Khóa học của tôi. Bài học và tiến độ được quản lý ngay trên English Center.','Người học tiếng Trung muốn phát triển từ vựng, ngữ pháp và kỹ năng làm bài theo cấp độ HSK.','["Hệ thống từ vựng và ngữ pháp theo cấp độ HSK của chương trình.","Luyện nhận diện chữ Hán và áp dụng kiến thức trong câu.","Tìm hiểu cách tiếp cận các phần nghe, đọc và viết theo cấp độ."]','["Các bộ chữ Hán","[HSK 3] Các chủ điểm","[HSK 3] Ngữ Pháp (cập nhật HSK 3.0)","[HSK 3] Chinh phục Nghe hiểu","[HSK 3] Chinh phục Đọc Hiểu","[HSK 3] Chinh phục Viết","[HSK 3] Luyện chép chính tả","[HSK 3] Từ vựng bổ sung New HSK 3.0"]','images/catalog/study4/course-32.webp',989000,799000,'https://youtu.be/Ug0HicTVHDA','online',1,0,'2026-10-22 09:50:59',1,365,'2026-10-22 09:50:59','2026-10-22 09:50:59' FROM learning_categories cat WHERE cat.slug='catalog-hsk' ON DUPLICATE KEY UPDATE `id`=`courses`.`id`;
