INSERT INTO `courses` (`learning_category_id`,`code`,`catalog_key`,`slug`,`name`,`summary`,`description`,`audience`,`learning_outcomes`,`curriculum_outline`,`thumbnail_path`,`price`,`sale_price`,`intro_video_url`,`delivery_mode`,`is_active`,`is_for_sale`,`published_at`,`duration_hours`,`access_days`,`created_at`,`updated_at`) SELECT cat.id,'EC-CAT-COURSE-33','course-33','chuong-trinh-course-33','Chinh phục HSK 4','Củng cố tiếng Trung và luyện tập theo nội dung HSK 4.','Củng cố tiếng Trung và luyện tập theo nội dung HSK 4.\n\nCách học\nBắt đầu bằng việc xác định mục tiêu, đọc các chủ đề trong chương trình và chia thời gian học thành những buổi ngắn. Sau mỗi buổi, ghi lại kiến thức mới, tự giải thích bằng ví dụ của bản thân và ôn lại nội dung còn chưa chắc.\n\nHọc và luyện tập\nCác bài học được công bố sẽ xuất hiện trong chương trình học bên dưới. Khi khóa học được mở bán, bạn thêm vào giỏ, xác nhận thanh toán mô phỏng và truy cập từ mục Khóa học của tôi. Bài học và tiến độ được quản lý ngay trên English Center.','Người học tiếng Trung muốn phát triển từ vựng, ngữ pháp và kỹ năng làm bài theo cấp độ HSK.','["Hệ thống từ vựng và ngữ pháp theo cấp độ HSK của chương trình.","Luyện nhận diện chữ Hán và áp dụng kiến thức trong câu.","Tìm hiểu cách tiếp cận các phần nghe, đọc và viết theo cấp độ."]','["Các bộ chữ Hán","[HSK 4] Các chủ điểm","[HSK 4] Ngữ Pháp (cập nhật HSK 3.0)","[HSK 4] Chinh phục Nghe hiểu","[HSK 4] Chinh phục Đọc Hiểu","[HSK 4] Chinh phục Viết","[HSK 4] Luyện chép chính tả","[HSK 4] Từ vựng bổ sung New HSK 3.0"]','images/catalog/study4/course-33.webp',989000,799000,'https://youtu.be/AOYhvdREc7s','online',1,0,'2026-10-22 09:50:59',1,365,'2026-10-22 09:50:59','2026-10-22 09:50:59' FROM learning_categories cat WHERE cat.slug='catalog-hsk' ON DUPLICATE KEY UPDATE `id`=`courses`.`id`;
INSERT INTO `learning_categories` (`slug`,`name`,`is_active`,`created_at`,`updated_at`) VALUES ('catalog-hsk','HSK',1,'2026-10-22 09:50:59','2026-10-22 09:50:59') ON DUPLICATE KEY UPDATE `id`=`learning_categories`.`id`;
