INSERT INTO `courses` (`learning_category_id`,`code`,`catalog_key`,`slug`,`name`,`summary`,`description`,`audience`,`learning_outcomes`,`curriculum_outline`,`thumbnail_path`,`price`,`sale_price`,`intro_video_url`,`delivery_mode`,`is_active`,`is_for_sale`,`published_at`,`duration_hours`,`access_days`,`created_at`,`updated_at`) SELECT cat.id,'EC-CAT-COURSE-35','course-35','chuong-trinh-course-35','Chinh phục HSK 6','Học và luyện tập tiếng Trung ở cấp độ HSK 6.','Học và luyện tập tiếng Trung ở cấp độ HSK 6.\n\nCách học\nBắt đầu bằng việc xác định mục tiêu, đọc các chủ đề trong chương trình và chia thời gian học thành những buổi ngắn. Sau mỗi buổi, ghi lại kiến thức mới, tự giải thích bằng ví dụ của bản thân và ôn lại nội dung còn chưa chắc.\n\nHọc và luyện tập\nCác bài học được công bố sẽ xuất hiện trong chương trình học bên dưới. Khi khóa học được mở bán, bạn thêm vào giỏ, xác nhận thanh toán mô phỏng và truy cập từ mục Khóa học của tôi. Bài học và tiến độ được quản lý ngay trên English Center.','Người học tiếng Trung muốn phát triển từ vựng, ngữ pháp và kỹ năng làm bài theo cấp độ HSK.','["Hệ thống từ vựng và ngữ pháp theo cấp độ HSK của chương trình.","Luyện nhận diện chữ Hán và áp dụng kiến thức trong câu.","Tìm hiểu cách tiếp cận các phần nghe, đọc và viết theo cấp độ."]','["Các bộ chữ Hán","[HSK 6] Các chủ điểm","[HSK 6] Ngữ Pháp (cập nhật HSK 3.0)","[HSK 6] Chinh phục Nghe hiểu","[HSK 6] Chinh phục Đọc Hiểu","[HSK 6] Chinh phục Viết","[HSK 6] Luyện chép chính tả","[HSK 6] Từ vựng bổ sung New HSK 3.0"]','images/catalog/study4/course-35.webp',989000,799000,'https://youtu.be/C_u1byYj6oA','online',1,0,'2026-10-22 09:50:59',1,365,'2026-10-22 09:50:59','2026-10-22 09:50:59' FROM learning_categories cat WHERE cat.slug='catalog-hsk' ON DUPLICATE KEY UPDATE `id`=`courses`.`id`;
INSERT INTO migrations (migration,batch) SELECT '2026_10_22_000007_add_course_presentation_fields',COALESCE(MAX(batch),0)+1 FROM migrations HAVING COALESCE(SUM(migration='2026_10_22_000007_add_course_presentation_fields'),0)=0;
INSERT INTO `course_sections` (`id`,`course_id`,`title`,`position`,`created_at`,`updated_at`) VALUES (10, 7, 'TOEIC Listening & Reading - Chiến lược nghe hiểu & từ vựng trọng tâm', 1, NOW(), NOW()) ON DUPLICATE KEY UPDATE `title`=VALUES(`title`);
INSERT INTO `lessons` (`id`,`course_section_id`,`title`,`slug`,`type`,`content`,`duration_seconds`,`position`,`is_preview`,`is_published`,`created_at`,`updated_at`) VALUES (28, 10, 'Chiến lược chinh phục TOEIC Listening Part 1 - 4 & Phương pháp Dictation', 'chuong-trinh-series-7-s1-p1-lenb', 'video', 'MỤC TIÊU BÀI HỌC\n- Nắm vững cấu trúc 100 câu hỏi trong bài thi TOEIC Listening.\n- Áp dụng phương pháp chép chính tả Dictation để nâng cao khả năng bắt âm và từ khóa.\n\n1. CHIẾN LƯỢC TỪNG PHẦN\n- Part 1 (Nghe tranh): Tập trung vào hành động của người (V-ing) hoặc vị trí đồ vật (bị động). Cảnh giác với bẫy phát âm gần giống nhau (similar sounds).\n- Part 2 (Hỏi - Đáp): Chú ý từ để hỏi đầu câu (Who, Where, When, Why, How). Tuyệt đối không chọn đáp án lặp lại từ hoặc có âm đồng âm với câu hỏi.\n- Part 3 & 4 (Hội thoại & Bài nói): Luôn đọc trước 3 câu hỏi và các lựa chọn trong thời gian nghỉ giữa các đoạn văn.\n\n2. BÀI TẬP DICTATION\nNghe và ghi chép lại các câu sau:\n1. The flight to Chicago has been delayed due to severe weather conditions.\n2. Please submit your expense reports to the accounting department by Friday.\n3. The annual shareholders meeting will be held in the main conference hall.', 2400, 1, 1, 1, NOW(), NOW()) ON DUPLICATE KEY UPDATE `title`=VALUES(`title`);
INSERT INTO `lessons` (`id`,`course_section_id`,`title`,`slug`,`type`,`content`,`duration_seconds`,`position`,`is_preview`,`is_published`,`created_at`,`updated_at`) VALUES (29, 10, 'Tuyển chọn 600 từ vựng nòng cốt TOEIC Listening & Bài tập chép chính tả', 'chuong-trinh-series-7-s1-p2-lrec', 'text', 'MỤC TIÊU BÀI HỌC\n- Ghi nhớ 50 từ vựng xuất hiện với tần suất cao nhất trong Part 1 và Part 2.\n- Hiểu sâu các cụm Collocations trong môi trường công sở thương mại.\n\nDANH MỤC TỪ VỰNG TRỌNG TÂM\n1. Agenda (n): Chương trình nghị sự, lịch trình họp.\n2. Invoice (n/v): Hóa đơn / Xuất hóa đơn thanh toán.\n3. Implement (v): Triển khai, thực thi chính sách.\n4. Negotiation (n): Cuộc đàm phán, thương lượng.\n5. Defective (adj): Bị lỗi, có khuyết tật (sản phẩm).\n\nBÀI TẬP VẬN DỤNG\nĐiền từ thích hợp vào chỗ trống:\n1. The board will review the proposed _____ before making a decision. (agenda)\n2. Customers can return _____ merchandise within thirty days for a full refund. (defective)\n3. We need to _____ new safety procedures to protect factory workers. (implement)', 1800, 2, 0, 1, NOW(), NOW()) ON DUPLICATE KEY UPDATE `title`=VALUES(`title`);
INSERT INTO `lessons` (`id`,`course_section_id`,`title`,`slug`,`type`,`content`,`duration_seconds`,`position`,`is_preview`,`is_published`,`created_at`,`updated_at`) VALUES (30, 10, 'Chiến lược Reading Part 5, 6, 7 & Mẹo tránh bẫy ngữ pháp thông dụng', 'chuong-trinh-series-7-s1-p3-xfwb', 'text', 'MỤC TIÊU BÀI HỌC\n- Tăng tốc độ xử lý Part 5 & 6 xuống dưới 15 phút.\n- Nhận diện các bẫy từ loại (Noun, Verb, Adj, Adv) và thì trong câu.\n\n1. BÍ QUYẾT XỬ LÝ PART 5 NHANH\n- Nhìn 4 đáp án trước: Nếu cùng một gốc từ, đây là câu hỏi từ loại. Xác định vị trí chỗ trống đứng sau từ gì và đóng vai trò gì.\n- Trước danh từ là tính từ bổ nghĩa, sau ngoại động từ là tân ngữ (danh từ/đại từ).\n\n2. KỸ THUẬT PART 7 ĐỌC HIỂU\n- Với bài đọc đơn (Single passage): Đọc câu hỏi, gạch chân từ khóa chỉ tên riêng, ngày tháng, số liệu rồi quét (scan) trong bài đọc.\n- Với bài đọc kép (Double/Triple passages): Chú ý câu hỏi liên kết thông tin giữa 2 văn bản.', 2100, 3, 0, 1, NOW(), NOW()) ON DUPLICATE KEY UPDATE `title`=VALUES(`title`);
INSERT INTO `course_sections` (`id`,`course_id`,`title`,`position`,`created_at`,`updated_at`) VALUES (11, 7, 'TOEIC Speaking - Phát âm chuẩn & phản xạ diễn đạt công sở', 2, NOW(), NOW()) ON DUPLICATE KEY UPDATE `title`=VALUES(`title`);
INSERT INTO `lessons` (`id`,`course_section_id`,`title`,`slug`,`type`,`content`,`duration_seconds`,`position`,`is_preview`,`is_published`,`created_at`,`updated_at`) VALUES (31, 11, 'Làm chủ phát âm IPA & Kỹ thuật đọc đoạn văn Read a Text Aloud', 'chuong-trinh-series-7-s2-p1-an6m', 'video', 'MỤC TIÊU BÀI HỌC\n- Đạt điểm tối đa trong Questions 1-2 của bài thi TOEIC Speaking.\n- Làm chủ ngữ điệu lên xuống khi liệt kê danh sách và kết thúc câu trần thuật.\n\nQUY TẮC PHÁT ÂM\n1. Ngữ điệu liệt kê: Lên giọng ở các thành phần đầu, hạ giọng ở thành phần cuối cùng (A ↗, B ↗, and C ↘).\n2. Trọng âm từ: Nhấn mạnh vào âm tiết mang nghĩa, lướt nhẹ các từ chức năng (giới từ, mạo từ).\n3. Nối âm (Connected speech): Nối phụ âm cuối của từ trước với nguyên âm đầu của từ sau.\n\nĐOẠN VĂN MẪU THỰC HÀNH:\n\'Good afternoon and welcome to the annual Apex Technology Expo. Today, you will see demonstrations of our newest software, meet our engineering team, and have the opportunity to test our latest devices.\'', 2000, 1, 0, 1, NOW(), NOW()) ON DUPLICATE KEY UPDATE `title`=VALUES(`title`);
INSERT INTO `lessons` (`id`,`course_section_id`,`title`,`slug`,`type`,`content`,`duration_seconds`,`position`,`is_preview`,`is_published`,`created_at`,`updated_at`) VALUES (32, 11, 'Cấu trúc miêu tả tranh Describe a Picture & Trả lời câu hỏi phỏng vấn', 'chuong-trinh-series-7-s2-p2-1yts', 'text', 'MỤC TIÊU BÀI HỌC\n- Nắm vững công thức 4 bước miêu tả tranh trong 30 giây (Questions 3-4).\n- Phản xạ trả lời trôi chảy các câu hỏi tình huống thường nhật (Questions 5-7).\n\nCÔNG THỨC 4 BƯỚC MIÊU TẢ TRANH\n1. Bối cảnh chung: This picture was taken in an office / at a restaurant.\n2. Nhân vật chính & hành động trung tâm: In the center of the picture, a man in a suit is giving a presentation.\n3. Chi tiết phụ & hậu cảnh: In the background, several colleagues are taking notes around a conference table.\n4. Cảm nghĩ / Dự đoán tổng quan: Overall, the atmosphere looks professional and focused.', 2200, 2, 0, 1, NOW(), NOW()) ON DUPLICATE KEY UPDATE `title`=VALUES(`title`);
INSERT INTO `course_sections` (`id`,`course_id`,`title`,`position`,`created_at`,`updated_at`) VALUES (12, 7, 'TOEIC Writing - Viết câu theo tranh, email thương mại & bài luận', 3, NOW(), NOW()) ON DUPLICATE KEY UPDATE `title`=VALUES(`title`);
INSERT INTO `lessons` (`id`,`course_section_id`,`title`,`slug`,`type`,`content`,`duration_seconds`,`position`,`is_preview`,`is_published`,`created_at`,`updated_at`) VALUES (33, 12, 'Kỹ thuật viết câu theo tranh & Quy tắc ngữ pháp không thể sai', 'chuong-trinh-series-7-s3-p1-1bri', 'video', 'MỤC TIÊU BÀI HỌC\n- Đạt điểm tuyệt đối trong Questions 1-5 của bài thi TOEIC Writing.\n- Kết hợp chính xác 2 từ khóa đề bài cho bằng liên từ hoặc giới từ phù hợp.\n\nCÁC CẤU TRÚC THƯỜNG DÙNG\n- Dùng liên từ thời gian: while, when, as soon as.\n- Dùng liên từ chỉ nguyên nhân kết quả: because, since, therefore.\n- Dùng mệnh đề quan hệ: who, which, where.\n\nVÍ DỤ:\nTừ khóa: [inspect / while]\nCâu hoàn chỉnh: The engineer is inspecting the machinery while the technician takes notes on a clipboard.', 1900, 1, 0, 1, NOW(), NOW()) ON DUPLICATE KEY UPDATE `title`=VALUES(`title`);
INSERT INTO `lessons` (`id`,`course_section_id`,`title`,`slug`,`type`,`content`,`duration_seconds`,`position`,`is_preview`,`is_published`,`created_at`,`updated_at`) VALUES (34, 12, 'Mẫu email phản hồi thương mại chuẩn quốc tế & Bài tập thực hành', 'chuong-trinh-series-7-s3-p2-f8dc', 'text', 'MỤC TIÊU BÀI HỌC\n- Viết email phản hồi khách hàng và đối tác trong Questions 6-7.\n- Thể hiện giọng điệu trang trọng (formal tone), giải quyết đầy đủ các yêu cầu đề ra.\n\nBỐ CỤC EMAIL PHẢN HỒI CHUẨN\n1. Lời chào: Dear Mr./Ms. [Last Name],\n2. Lời cảm ơn & lý do viết thư: Thank you for contacting our customer service department regarding...\n3. Trả lời chi tiết từng câu hỏi / giải quyết phàn nàn: In response to your inquiry about..., we would like to inform you that...\n4. Đề xuất phương án tiếp theo: Should you require any further assistance, please do not hesitate to contact us.\n5. Lời kết: Sincerely / Best regards, [Your Name].', 2400, 2, 0, 1, NOW(), NOW()) ON DUPLICATE KEY UPDATE `title`=VALUES(`title`);
INSERT INTO `course_sections` (`id`,`course_id`,`title`,`position`,`created_at`,`updated_at`) VALUES (13, 7, 'Luyện đề tổng hợp TOEIC 4 kỹ năng & Bộ đề thực chiến', 4, NOW(), NOW()) ON DUPLICATE KEY UPDATE `title`=VALUES(`title`);
INSERT INTO `lessons` (`id`,`course_section_id`,`title`,`slug`,`type`,`content`,`duration_seconds`,`position`,`is_preview`,`is_published`,`created_at`,`updated_at`) VALUES (35, 13, 'Hướng dẫn phân bổ thời gian và chiến thuật làm bài thi TOEIC 4 kỹ năng', 'chuong-trinh-series-7-s4-p1-u3mq', 'video', 'MỤC TIÊU BÀI HỌC\n- Quản lý áp lực phòng thi và tối ưu hóa điểm số cho cả 4 phần thi.\n- Nắm rõ thang điểm và tiêu chí chấm thi của Viện khảo thí giáo dục Hoa Kỳ (ETS).\n\nPHÂN BỔ THỜI GIAN TỐI ƯU:\n- Listening: 45 phút cho 100 câu (nghe liên tục theo băng đĩa).\n- Reading: 75 phút cho 100 câu (Part 5: 12 phút, Part 6: 8 phút, Part 7: 55 phút).\n- Speaking: ~20 phút (11 câu hỏi ghi âm trực tiếp trên máy tính).\n- Writing: 60 phút (8 câu hỏi gõ trực tiếp trên bàn phím máy tính).', 1800, 1, 0, 1, NOW(), NOW()) ON DUPLICATE KEY UPDATE `title`=VALUES(`title`);
INSERT INTO `lessons` (`id`,`course_section_id`,`title`,`slug`,`type`,`content`,`duration_seconds`,`position`,`is_preview`,`is_published`,`created_at`,`updated_at`) VALUES (36, 13, 'Chữa chi tiết đề thi mẫu TOEIC Full 4 Skills kèm Audio Script', 'chuong-trinh-series-7-s4-p2-lf5f', 'text', 'MỤC TIÊU BÀI HỌC\n- Đối chiếu đáp án, rà soát lỗi sai và ghi chú từ vựng mới sau khi làm bài thi thử.\n- Nâng cao phản xạ nhận diện bẫy đề thi thực tế.\n\nPHÂN TÍCH CHI TIẾT CÂU HỎI ĐIỂN HÌNH:\n- Câu hỏi bẫy từ đồng âm: \'reception\' (tiệc chiêu đãi vs bàn lễ tân).\n- Câu hỏi bẫy thì: Hành động đã xảy ra trong quá khứ so với thói quen hiện tại.\n- Mẹo ghi nhớ: Luôn xem lại danh sách từ vựng của mỗi đề thi ít nhất 3 lần để khắc sâu trí nhớ dài hạn.', 2500, 2, 0, 1, NOW(), NOW()) ON DUPLICATE KEY UPDATE `title`=VALUES(`title`);
INSERT INTO `course_sections` (`id`,`course_id`,`title`,`position`,`created_at`,`updated_at`) VALUES (14, 8, 'IELTS Listening Intensive - Chiến lược bắt từ khóa & Dictation', 1, NOW(), NOW()) ON DUPLICATE KEY UPDATE `title`=VALUES(`title`);
INSERT INTO `lessons` (`id`,`course_section_id`,`title`,`slug`,`type`,`content`,`duration_seconds`,`position`,`is_preview`,`is_published`,`created_at`,`updated_at`) VALUES (37, 14, 'Phương pháp Dictation chép chính tả & Nhận diện âm nối, âm đuôi', 'chuong-trinh-series-2-s1-p1-plvc', 'video', 'MỤC TIÊU BÀI HỌC\n- Khắc phục triệt để lỗi bỏ quên đuôi số nhiều -s/-es và âm quá khứ -ed khi điền từ trong IELTS Listening.\n- Phương pháp chép chính tả 3 bước giúp tăng band điểm nhanh chóng.\n\n3 BƯỚC LUYỆN NGHE DICTATION HIỆU QUẢ\n1. Bước 1: Nghe lần 1 để hiểu ý tổng quan của toàn đoạn văn.\n2. Bước 2: Bấm dừng (pause) sau mỗi cụm từ 5-7 từ, chép lại chính xác từng từ ra giấy.\n3. Bước 3: Mở transcript đối chiếu, đánh dấu bút đỏ những từ nghe sót hoặc nhầm lẫn, sau đó nghe lại đoạn đó 3 lần.', 2400, 1, 1, 1, NOW(), NOW()) ON DUPLICATE KEY UPDATE `title`=VALUES(`title`);
INSERT INTO `lessons` (`id`,`course_section_id`,`title`,`slug`,`type`,`content`,`duration_seconds`,`position`,`is_preview`,`is_published`,`created_at`,`updated_at`) VALUES (38, 14, 'Chiến lược xử lý Section 1-4 trong đề thi IELTS Listening Cam', 'chuong-trinh-series-2-s1-p2-ay9z', 'text', 'MỤC TIÊU BÀI HỌC\n- Phân biệt đặc trưng 4 phần thi: Section 1 (đối thoại hàng ngày), Section 2 (độc thoại xã hội), Section 3 (thảo luận học thuật nhóm), Section 4 (bài giảng chuyên ngành).\n- Kỹ thuật đoán trước từ loại và dạng thông tin cần điền (tên riêng, số điện thoại, ngày tháng, danh từ đếm được/không đếm được).', 2100, 2, 0, 1, NOW(), NOW()) ON DUPLICATE KEY UPDATE `title`=VALUES(`title`);
INSERT INTO `course_sections` (`id`,`course_id`,`title`,`position`,`created_at`,`updated_at`) VALUES (15, 8, 'IELTS Reading Intensive - Làm chủ Skimming, Scanning & Keywords', 2, NOW(), NOW()) ON DUPLICATE KEY UPDATE `title`=VALUES(`title`);
INSERT INTO `lessons` (`id`,`course_section_id`,`title`,`slug`,`type`,`content`,`duration_seconds`,`position`,`is_preview`,`is_published`,`created_at`,`updated_at`) VALUES (39, 15, 'Phương pháp Skimming & Scanning định vị thông tin dưới 60 giây', 'chuong-trinh-series-2-s2-p1-efik', 'video', 'MỤC TIÊU BÀI HỌC\n- Skimming: Đọc lướt tiêu đề, câu đầu và câu cuối mỗi đoạn để nắm được đại ý bài đọc (Main idea).\n- Scanning: Quét mắt tìm nhanh các từ khóa không thể bị paraphrase như tên riêng, con số, thuật ngữ khoa học.\n- Quản lý thời gian 20 phút cho mỗi Passage trong tổng số 3 Passage của bài thi IELTS Reading.', 2100, 1, 0, 1, NOW(), NOW()) ON DUPLICATE KEY UPDATE `title`=VALUES(`title`);
INSERT INTO `lessons` (`id`,`course_section_id`,`title`,`slug`,`type`,`content`,`duration_seconds`,`position`,`is_preview`,`is_published`,`created_at`,`updated_at`) VALUES (40, 15, 'Giải quyết dứt điểm dạng bài True/False/Not Given & Yes/No/Not Given', 'chuong-trinh-series-2-s2-p2-us9r', 'text', 'MỤC TIÊU BÀI HỌC\n- Phân biệt ranh giới rõ ràng giữa False và Not Given.\n\nQUY TẮC VÀNG:\n- TRUE: Ý kiến trong nhận định khớp hoàn toàn với thông tin trong bài đọc (dù được diễn đạt bằng từ đồng nghĩa khác).\n- FALSE: Bài đọc có đề cập đến chủ đề đó, nhưng đưa ra thông tin trái ngược hoặc mâu thuẫn trực tiếp với nhận định.\n- NOT GIVEN: Bài đọc không có thông tin xác nhận hoặc không đủ cơ sở để kết luận nhận định đó đúng hay sai.', 2400, 2, 0, 1, NOW(), NOW()) ON DUPLICATE KEY UPDATE `title`=VALUES(`title`);
INSERT INTO `course_sections` (`id`,`course_id`,`title`,`position`,`created_at`,`updated_at`) VALUES (16, 8, 'IELTS Speaking Intensive - Phản xạ tự nhiên & từ vựng chủ đề', 3, NOW(), NOW()) ON DUPLICATE KEY UPDATE `title`=VALUES(`title`);
INSERT INTO `lessons` (`id`,`course_section_id`,`title`,`slug`,`type`,`content`,`duration_seconds`,`position`,`is_preview`,`is_published`,`created_at`,`updated_at`) VALUES (41, 16, 'Kỹ thuật phát triển câu trả lời Part 1 mượt mà và tự nhiên', 'chuong-trinh-series-2-s3-p1-ywhu', 'video', 'MỤC TIÊU BÀI HỌC\n- Trả lời Part 1 theo công thức A.R.E: Answer (Trả lời trực tiếp) - Reason (Giải thích lý do) - Example/Elaboration (Ví dụ hoặc mở rộng trải nghiệm bản thân).\n- Sử dụng linh hoạt các liên từ nối tự nhiên: \'To be honest\', \'As far as I remember\', \'Personally speaking\'.', 1900, 1, 0, 1, NOW(), NOW()) ON DUPLICATE KEY UPDATE `title`=VALUES(`title`);
INSERT INTO `lessons` (`id`,`course_section_id`,`title`,`slug`,`type`,`content`,`duration_seconds`,`position`,`is_preview`,`is_published`,`created_at`,`updated_at`) VALUES (42, 16, 'Khung dàn ý 2 phút cho Speaking Part 2 với phương pháp Storytelling', 'chuong-trinh-series-2-s3-p2-suee', 'text', 'MỤC TIÊU BÀI HỌC\n- Tận dụng tối đa 1 phút chuẩn bị với sơ đồ tư duy Mindmap thay vì viết cả câu.\n- Cấu trúc kể chuyện 4 phần: Thời gian/Địa điểm - Nhân vật tham gia - Sự việc diễn ra - Cảm xúc/Ý nghĩa đối với bản thân.', 2200, 2, 0, 1, NOW(), NOW()) ON DUPLICATE KEY UPDATE `title`=VALUES(`title`);
INSERT INTO `course_sections` (`id`,`course_id`,`title`,`position`,`created_at`,`updated_at`) VALUES (17, 8, 'IELTS Writing Intensive - Task 1 Report & Task 2 Academic Essay', 4, NOW(), NOW()) ON DUPLICATE KEY UPDATE `title`=VALUES(`title`);
INSERT INTO `lessons` (`id`,`course_section_id`,`title`,`slug`,`type`,`content`,`duration_seconds`,`position`,`is_preview`,`is_published`,`created_at`,`updated_at`) VALUES (43, 17, 'Cấu trúc 4 đoạn cho Task 1 & Phân tích biểu đồ xu hướng (Trend)', 'chuong-trinh-series-2-s4-p1-gc1b', 'video', 'MỤC TIÊU BÀI HỌC\n- Viết mở bài Paraphrase đề bài trong 1 câu.\n- Viết Overview làm nổi bật 2 đặc điểm bao quát nhất của biểu đồ (xu hướng tăng/giảm và điểm cao nhất/thấp nhất).\n- Hai đoạn thân bài Body 1 & Body 2 chọn lọc số liệu tiêu biểu, tránh liệt kê máy móc.', 2200, 1, 0, 1, NOW(), NOW()) ON DUPLICATE KEY UPDATE `title`=VALUES(`title`);
INSERT INTO `lessons` (`id`,`course_section_id`,`title`,`slug`,`type`,`content`,`duration_seconds`,`position`,`is_preview`,`is_published`,`created_at`,`updated_at`) VALUES (44, 17, 'Bố cục bài luận Task 2 band 7.5+ và kỹ thuật Brainstorming lập luận', 'chuong-trinh-series-2-s4-p2-4eds', 'text', 'MỤC TIÊU BÀI HỌC\n- Làm chủ cấu trúc bài luận Academic 4 đoạn: Introduction (Paraphrase + Thesis Statement), Body 1, Body 2, Conclusion.\n- Xây dựng luận điểm theo mô hình P.E.E.L (Point - Explanation - Example - Link).', 2600, 2, 0, 1, NOW(), NOW()) ON DUPLICATE KEY UPDATE `title`=VALUES(`title`);
INSERT INTO `course_sections` (`id`,`course_id`,`title`,`position`,`created_at`,`updated_at`) VALUES (18, 9, 'IELTS Fundamentals - Từ vựng & ngữ pháp học thuật nòng cốt', 1, NOW(), NOW()) ON DUPLICATE KEY UPDATE `title`=VALUES(`title`);
INSERT INTO `lessons` (`id`,`course_section_id`,`title`,`slug`,`type`,`content`,`duration_seconds`,`position`,`is_preview`,`is_published`,`created_at`,`updated_at`) VALUES (45, 18, '500 từ vựng cốt lõi học thuật Academic Word List (AWL)', 'chuong-trinh-series-8-s1-p1-nmcv', 'video', 'MỤC TIÊU BÀI HỌC\n- Nắm vững các động từ và danh từ học thuật quan trọng: analyze, indicate, significant, concept, approach, perspective, contribute.\n- Cách chuyển đổi từ loại (Word Family) để linh hoạt paraphrase trong văn viết và bài nói.', 2200, 1, 1, 1, NOW(), NOW()) ON DUPLICATE KEY UPDATE `title`=VALUES(`title`);
INSERT INTO `lessons` (`id`,`course_section_id`,`title`,`slug`,`type`,`content`,`duration_seconds`,`position`,`is_preview`,`is_published`,`created_at`,`updated_at`) VALUES (46, 18, 'Ngữ pháp chuyên sâu: Câu phức, Mệnh đề quan hệ & Câu điều kiện', 'chuong-trinh-series-8-s1-p2-qjwr', 'text', 'MỤC TIÊU BÀI HỌC\n- Viết câu ghép và câu phức chuẩn ngữ pháp học thuật.\n- Tránh lỗi ngắt câu sai (Comma splice) và câu thiếu vị ngữ (Fragment).', 2000, 2, 0, 1, NOW(), NOW()) ON DUPLICATE KEY UPDATE `title`=VALUES(`title`);
INSERT INTO `course_sections` (`id`,`course_id`,`title`,`position`,`created_at`,`updated_at`) VALUES (19, 9, 'IELTS Listening Foundation to Intensive - Luyện phản xạ tai nghe', 2, NOW(), NOW()) ON DUPLICATE KEY UPDATE `title`=VALUES(`title`);
INSERT INTO `lessons` (`id`,`course_section_id`,`title`,`slug`,`type`,`content`,`duration_seconds`,`position`,`is_preview`,`is_published`,`created_at`,`updated_at`) VALUES (47, 19, 'Luyện nghe âm cơ bản, nối âm và số đếm trong giao tiếp tiếng Anh', 'chuong-trinh-series-8-s2-p1-axcr', 'video', 'MỤC TIÊU BÀI HỌC\n- Phân biệt cặp số hay nhầm lẫn: -teen và -ty (thirteen vs thirty).\n- Nghe chính xác đánh vần tên riêng tiếng Anh và mã bưu điện (Postcode).', 1900, 1, 0, 1, NOW(), NOW()) ON DUPLICATE KEY UPDATE `title`=VALUES(`title`);
INSERT INTO `lessons` (`id`,`course_section_id`,`title`,`slug`,`type`,`content`,`duration_seconds`,`position`,`is_preview`,`is_published`,`created_at`,`updated_at`) VALUES (48, 19, 'Thực hành chép chính tả theo chủ đề học thuật Cambridge', 'chuong-trinh-series-8-s2-p2-iiio', 'text', 'MỤC TIÊU BÀI HỌC\n- Luyện nghe và ghi chép các đoạn đối thoại giữa sinh viên và cố vấn học tập tại trường đại học.\n- Xây dựng vốn từ vựng chuyên ngành giáo dục và đời sống sinh viên.', 2200, 2, 0, 1, NOW(), NOW()) ON DUPLICATE KEY UPDATE `title`=VALUES(`title`);
INSERT INTO `course_sections` (`id`,`course_id`,`title`,`position`,`created_at`,`updated_at`) VALUES (20, 9, 'IELTS Reading Foundation to Intensive - Đọc hiểu đoạn văn', 3, NOW(), NOW()) ON DUPLICATE KEY UPDATE `title`=VALUES(`title`);
INSERT INTO `lessons` (`id`,`course_section_id`,`title`,`slug`,`type`,`content`,`duration_seconds`,`position`,`is_preview`,`is_published`,`created_at`,`updated_at`) VALUES (49, 20, 'Chiến thuật dịch nghĩa theo cụm từ và nhận diện cấu trúc câu dài', 'chuong-trinh-series-8-s3-p1-q6eb', 'video', 'MỤC TIÊU BÀI HỌC\n- Kỹ thuật phân tích thành phần câu dài trong bài đọc IELTS: xác định mệnh đề chính, mệnh đề phụ và các cụm giới từ rút gọn.', 2100, 1, 0, 1, NOW(), NOW()) ON DUPLICATE KEY UPDATE `title`=VALUES(`title`);
INSERT INTO `lessons` (`id`,`course_section_id`,`title`,`slug`,`type`,`content`,`duration_seconds`,`position`,`is_preview`,`is_published`,`created_at`,`updated_at`) VALUES (50, 20, 'Thực hành đọc hiểu dạng bài Summary Completion & Multiple Choice', 'chuong-trinh-series-8-s3-p2-ef2c', 'text', 'MỤC TIÊU BÀI HỌC\n- Phương pháp điền từ tóm tắt bài đọc với giới hạn từ (NO MORE THAN TWO WORDS).\n- Kỹ năng loại trừ các phương án gây nhiễu trong câu hỏi trắc nghiệm.', 2300, 2, 0, 1, NOW(), NOW()) ON DUPLICATE KEY UPDATE `title`=VALUES(`title`);
INSERT INTO `course_sections` (`id`,`course_id`,`title`,`position`,`created_at`,`updated_at`) VALUES (21, 9, 'IELTS Speaking & Writing Intensive - Ứng dụng thực chiến', 4, NOW(), NOW()) ON DUPLICATE KEY UPDATE `title`=VALUES(`title`);
INSERT INTO `lessons` (`id`,`course_section_id`,`title`,`slug`,`type`,`content`,`duration_seconds`,`position`,`is_preview`,`is_published`,`created_at`,`updated_at`) VALUES (51, 21, 'Chuẩn hóa phát âm IPA và mở rộng câu trả lời theo công thức ARE', 'chuong-trinh-series-8-s4-p1-qgkc', 'video', 'MỤC TIÊU BÀI HỌC\n- Khắc phục các lỗi phát âm cơ bản và luyện tập trả lời các chủ đề phổ biến trong IELTS Speaking Part 1 & 2.', 2000, 1, 0, 1, NOW(), NOW()) ON DUPLICATE KEY UPDATE `title`=VALUES(`title`);
INSERT INTO `lessons` (`id`,`course_section_id`,`title`,`slug`,`type`,`content`,`duration_seconds`,`position`,`is_preview`,`is_published`,`created_at`,`updated_at`) VALUES (52, 21, 'Kỹ thuật triển khai đoạn văn học thuật P.E.E.L trong Writing Task 2', 'chuong-trinh-series-8-s4-p2-v1wp', 'text', 'MỤC TIÊU BÀI HỌC\n- Viết đoạn văn thân bài mạch lạc, thuyết phục với câu chủ đề (Topic sentence), câu giải thích và ví dụ thực tế.', 2500, 2, 0, 1, NOW(), NOW()) ON DUPLICATE KEY UPDATE `title`=VALUES(`title`);
INSERT INTO `course_sections` (`id`,`course_id`,`title`,`position`,`created_at`,`updated_at`) VALUES (22, 10, '3600 Từ vựng tiếng Anh thông dụng theo chủ đề đời sống', 1, NOW(), NOW()) ON DUPLICATE KEY UPDATE `title`=VALUES(`title`);
INSERT INTO `lessons` (`id`,`course_section_id`,`title`,`slug`,`type`,`content`,`duration_seconds`,`position`,`is_preview`,`is_published`,`created_at`,`updated_at`) VALUES (53, 22, 'Phương pháp ghi nhớ từ vựng qua ngữ cảnh và quy tắc Spaced Repetition', 'chuong-trinh-series-1-s1-p1-ek9b', 'video', 'MỤC TIÊU BÀI HỌC\n- Ứng dụng phương pháp lặp lại ngắt quãng để nhớ từ vựng vĩnh viễn.\n- Học từ vựng theo cụm Collocations thay vì học từng từ đơn lẻ.', 2000, 1, 1, 1, NOW(), NOW()) ON DUPLICATE KEY UPDATE `title`=VALUES(`title`);
INSERT INTO `lessons` (`id`,`course_section_id`,`title`,`slug`,`type`,`content`,`duration_seconds`,`position`,`is_preview`,`is_published`,`created_at`,`updated_at`) VALUES (54, 22, '300 từ vựng và cụm từ sinh hoạt hàng ngày thiết yếu nhất', 'chuong-trinh-series-1-s1-p2-qgru', 'text', 'MỤC TIÊU BÀI HỌC\n- Thành thạo từ vựng về ăn uống, đi lại, mua sắm, nhà cửa và công việc văn phòng.', 2100, 2, 0, 1, NOW(), NOW()) ON DUPLICATE KEY UPDATE `title`=VALUES(`title`);
INSERT INTO `course_sections` (`id`,`course_id`,`title`,`position`,`created_at`,`updated_at`) VALUES (23, 10, 'Ngữ pháp tiếng Anh ứng dụng từ A-Z', 2, NOW(), NOW()) ON DUPLICATE KEY UPDATE `title`=VALUES(`title`);
INSERT INTO `lessons` (`id`,`course_section_id`,`title`,`slug`,`type`,`content`,`duration_seconds`,`position`,`is_preview`,`is_published`,`created_at`,`updated_at`) VALUES (55, 23, 'Nắm vững 6 thì then chốt trong giao tiếp và công việc', 'chuong-trinh-series-1-s2-p1-j1f5', 'video', 'MỤC TIÊU BÀI HỌC\n- Hiện tại đơn, Hiện tại tiếp diễn, Hiện tại hoàn thành, Quá khứ đơn, Tương lai đơn và Tương lai gần.', 2200, 1, 0, 1, NOW(), NOW()) ON DUPLICATE KEY UPDATE `title`=VALUES(`title`);
INSERT INTO `lessons` (`id`,`course_section_id`,`title`,`slug`,`type`,`content`,`duration_seconds`,`position`,`is_preview`,`is_published`,`created_at`,`updated_at`) VALUES (56, 23, 'Cách dùng mạo từ a/an/the, giới từ chỉ nơi chốn và thời gian', 'chuong-trinh-series-1-s2-p2-oc7w', 'text', 'MỤC TIÊU BÀI HỌC\n- Giải quyết dứt điểm các lỗi sai phổ biến khi dùng in, on, at và mạo từ the.', 1900, 2, 0, 1, NOW(), NOW()) ON DUPLICATE KEY UPDATE `title`=VALUES(`title`);
INSERT INTO `course_sections` (`id`,`course_id`,`title`,`position`,`created_at`,`updated_at`) VALUES (24, 10, 'Ngữ âm & phản xạ giao tiếp tự nhiên', 3, NOW(), NOW()) ON DUPLICATE KEY UPDATE `title`=VALUES(`title`);
INSERT INTO `lessons` (`id`,`course_section_id`,`title`,`slug`,`type`,`content`,`duration_seconds`,`position`,`is_preview`,`is_published`,`created_at`,`updated_at`) VALUES (57, 24, 'Hướng dẫn khẩu hình chuẩn 44 âm IPA và tránh lỗi phát âm của người Việt', 'chuong-trinh-series-1-s3-p1-rypy', 'video', 'MỤC TIÊU BÀI HỌC\n- Làm chủ các cặp âm khó: /i:/ vs /ɪ/, /s/ vs /ʃ/, /θ/ vs /ð/.', 2100, 1, 0, 1, NOW(), NOW()) ON DUPLICATE KEY UPDATE `title`=VALUES(`title`);
INSERT INTO `lessons` (`id`,`course_section_id`,`title`,`slug`,`type`,`content`,`duration_seconds`,`position`,`is_preview`,`is_published`,`created_at`,`updated_at`) VALUES (58, 24, 'Thực hành 50 mẫu câu giao tiếp thông dụng tại nhà hàng, sân bay, công ty', 'chuong-trinh-series-1-s3-p2-spfy', 'text', 'MỤC TIÊU BÀI HỌC\n- Đặt món, hỏi đường, làm thủ tục chuyến bay và trao đổi công việc lịch thiệp.', 2000, 2, 0, 1, NOW(), NOW()) ON DUPLICATE KEY UPDATE `title`=VALUES(`title`);
INSERT INTO `course_sections` (`id`,`course_id`,`title`,`position`,`created_at`,`updated_at`) VALUES (25, 10, 'Luyện nghe nói qua TED Talks & âm nhạc', 4, NOW(), NOW()) ON DUPLICATE KEY UPDATE `title`=VALUES(`title`);
INSERT INTO `lessons` (`id`,`course_section_id`,`title`,`slug`,`type`,`content`,`duration_seconds`,`position`,`is_preview`,`is_published`,`created_at`,`updated_at`) VALUES (59, 25, 'Kỹ thuật nghe nhại Shadowing qua video diễn thuyết ngắn TED Talks', 'chuong-trinh-series-1-s4-p1-dglv', 'video', 'MỤC TIÊU BÀI HỌC\n- Nhại theo ngữ điệu, tốc độ nói và ngữ âm của các diễn giả truyền cảm hứng.', 1800, 1, 0, 1, NOW(), NOW()) ON DUPLICATE KEY UPDATE `title`=VALUES(`title`);
INSERT INTO `lessons` (`id`,`course_section_id`,`title`,`slug`,`type`,`content`,`duration_seconds`,`position`,`is_preview`,`is_published`,`created_at`,`updated_at`) VALUES (60, 25, 'Học thành ngữ và tiếng lóng văn minh qua các bài hát tiếng Anh nổi tiếng', 'chuong-trinh-series-1-s4-p2-x5st', 'text', 'MỤC TIÊU BÀI HỌC\n- Khám phá các thành ngữ phổ biến trong âm nhạc và văn hóa giao tiếp hiện đại.', 2000, 2, 0, 1, NOW(), NOW()) ON DUPLICATE KEY UPDATE `title`=VALUES(`title`);
INSERT INTO `course_sections` (`id`,`course_id`,`title`,`position`,`created_at`,`updated_at`) VALUES (26, 11, 'HSK 1 - Ngữ âm Pinyin, chữ Hán cơ bản & 150 từ vựng', 1, NOW(), NOW()) ON DUPLICATE KEY UPDATE `title`=VALUES(`title`);
