INSERT INTO `lessons` (`id`,`course_section_id`,`title`,`slug`,`type`,`content`,`duration_seconds`,`position`,`is_preview`,`is_published`,`created_at`,`updated_at`) VALUES (64, 27, '150 từ vựng mới HSK 2 và các chủ đề mua sắm, hỏi đường, thời tiết', 'chuong-trinh-series-6-s2-p2-h6id', 'text', 'MỤC TIÊU BÀI HỌC\n- Giao tiếp thành thạo khi đi mua sắm (hỏi giá, mặc cả), hỏi phương tiện đi lại và dự báo thời tiết.', 2200, 2, 0, 1, NOW(), NOW()) ON DUPLICATE KEY UPDATE `title`=VALUES(`title`);
