INSERT INTO `lessons` (`id`,`course_section_id`,`title`,`slug`,`type`,`content`,`duration_seconds`,`position`,`is_preview`,`is_published`,`created_at`,`updated_at`) VALUES (65, 28, 'Chiến lược làm bài Nghe hiểu và Đọc hiểu HSK 3', 'chuong-trinh-series-6-s3-p1-scvn', 'video', 'MỤC TIÊU BÀI HỌC\n- Kỹ năng bắt từ khóa trong bài nghe và đọc hiểu văn bản chữ Hán không kèm Pinyin.', 2300, 1, 0, 1, NOW(), NOW()) ON DUPLICATE KEY UPDATE `title`=VALUES(`title`);
INSERT INTO `lessons` (`id`,`course_section_id`,`title`,`slug`,`type`,`content`,`duration_seconds`,`position`,`is_preview`,`is_published`,`created_at`,`updated_at`) VALUES (66, 28, '300 từ vựng mới HSK 3 và các cấu trúc liên từ phức', 'chuong-trinh-series-6-s3-p2-7cwp', 'text', 'MỤC TIÊU BÀI HỌC\n- Sử dụng thành thạo các cặp liên từ: 虽然...但是... (Tuy... nhưng...), 不但...而且... (Không những... mà còn...).', 2100, 2, 0, 1, NOW(), NOW()) ON DUPLICATE KEY UPDATE `title`=VALUES(`title`);
