INSERT INTO `lessons` (`id`,`course_section_id`,`title`,`slug`,`type`,`content`,`duration_seconds`,`position`,`is_preview`,`is_published`,`created_at`,`updated_at`) VALUES (98, 44, 'Thực hành ứng dụng & Chữa bài chi tiết: Grammar in Writing - Cấu trúc câu ghép, câu phức nâng cao', 'chuong-trinh-course-26-s5-p2-hb0k', 'text', 'MỤC TIÊU BÀI HỌC\n- Vận dụng lý thuyết đã học vào giải các bài tập tình huống thực tế của phần Grammar in Writing - Cấu trúc câu ghép, câu phức nâng cao.\n- Rèn luyện phản xạ chính xác và tốc độ xử lý câu hỏi.\n\nBÀI TẬP VẬN DỤNG THỰC TẾ\n- Câu 1: Xác định cấu trúc ngữ pháp và từ khóa chính trong ngữ cảnh bài thi.\n- Câu 2: Áp dụng phương pháp loại trừ để tìm phương án chính xác nhất.\n- Câu 3: Mở rộng từ vựng liên quan và ghi nhớ các cụm từ đồng nghĩa (Paraphrasing).\n\nĐÁP ÁN & GIẢI THÍCH CHI TIẾT\n- Xem lại phần giải thích cho từng câu hỏi, ghi nhận lỗi sai để không lặp lại trong bài thi thật.', 2400, 2, 0, 1, NOW(), NOW()) ON DUPLICATE KEY UPDATE `title`=VALUES(`title`);
