INSERT INTO `lessons` (`id`,`course_section_id`,`title`,`slug`,`type`,`content`,`duration_seconds`,`position`,`is_preview`,`is_published`,`created_at`,`updated_at`) VALUES (99, 45, 'Lý thuyết & Phương pháp trọng tâm: Phương pháp luyện nghe chép chính tả Dictation & Bắt âm nối', 'chuong-trinh-course-15-s1-p1-z8ph', 'video', 'MỤC TIÊU BÀI HỌC\n- Làm chủ toàn bộ kiến thức nền tảng và phương pháp giải quyết chuyên đề: Phương pháp luyện nghe chép chính tả Dictation & Bắt âm nối.\n- Nhận diện các bẫy thường gặp và quy tắc xử lý nhanh trong bài thi.\n\n1. KIẾN THỨC CỐT LÕI\n- Khái niệm, nguyên lý hoạt động và cấu trúc ngữ pháp / từ vựng then chốt.\n- Các bước tiếp cận đề bài khoa học, tiết kiệm tối đa thời gian.\n\n2. VÍ DỤ VẬN DỤNG & PHÂN TÍCH\n- Phân tích chi tiết các câu hỏi mẫu thực tế từ đề thi chuẩn.\n- Chỉ ra dấu hiệu nhận biết đáp án đúng và lý do loại bỏ các phương án nhiễu.\n\n3. LỜI KHUYÊN TỰ HỌC\n- Ghi chép lại các cấu trúc mới vào sổ tay học tập.\n- Làm bài tập thực hành ở bài học tiếp theo để củng cố kiến thức.', 1800, 1, 1, 1, NOW(), NOW()) ON DUPLICATE KEY UPDATE `title`=VALUES(`title`);
INSERT INTO `lessons` (`id`,`course_section_id`,`title`,`slug`,`type`,`content`,`duration_seconds`,`position`,`is_preview`,`is_published`,`created_at`,`updated_at`) VALUES (100, 45, 'Thực hành ứng dụng & Chữa bài chi tiết: Phương pháp luyện nghe chép chính tả Dictation & Bắt âm nối', 'chuong-trinh-course-15-s1-p2-kmij', 'text', 'MỤC TIÊU BÀI HỌC\n- Vận dụng lý thuyết đã học vào giải các bài tập tình huống thực tế của phần Phương pháp luyện nghe chép chính tả Dictation & Bắt âm nối.\n- Rèn luyện phản xạ chính xác và tốc độ xử lý câu hỏi.\n\nBÀI TẬP VẬN DỤNG THỰC TẾ\n- Câu 1: Xác định cấu trúc ngữ pháp và từ khóa chính trong ngữ cảnh bài thi.\n- Câu 2: Áp dụng phương pháp loại trừ để tìm phương án chính xác nhất.\n- Câu 3: Mở rộng từ vựng liên quan và ghi nhớ các cụm từ đồng nghĩa (Paraphrasing).\n\nĐÁP ÁN & GIẢI THÍCH CHI TIẾT\n- Xem lại phần giải thích cho từng câu hỏi, ghi nhận lỗi sai để không lặp lại trong bài thi thật.', 2400, 2, 0, 1, NOW(), NOW()) ON DUPLICATE KEY UPDATE `title`=VALUES(`title`);
