INSERT INTO `lessons` (`id`,`course_section_id`,`title`,`slug`,`type`,`content`,`duration_seconds`,`position`,`is_preview`,`is_published`,`created_at`,`updated_at`) VALUES (175, 83, 'Lý thuyết & Phương pháp trọng tâm: Mệnh đề quan hệ Relative Clauses & Câu điều kiện Conditionals', 'chuong-trinh-course-13-s3-p1-mbps', 'video', 'MỤC TIÊU BÀI HỌC\n- Làm chủ toàn bộ kiến thức nền tảng và phương pháp giải quyết chuyên đề: Mệnh đề quan hệ Relative Clauses & Câu điều kiện Conditionals.\n- Nhận diện các bẫy thường gặp và quy tắc xử lý nhanh trong bài thi.\n\n1. KIẾN THỨC CỐT LÕI\n- Khái niệm, nguyên lý hoạt động và cấu trúc ngữ pháp / từ vựng then chốt.\n- Các bước tiếp cận đề bài khoa học, tiết kiệm tối đa thời gian.\n\n2. VÍ DỤ VẬN DỤNG & PHÂN TÍCH\n- Phân tích chi tiết các câu hỏi mẫu thực tế từ đề thi chuẩn.\n- Chỉ ra dấu hiệu nhận biết đáp án đúng và lý do loại bỏ các phương án nhiễu.\n\n3. LỜI KHUYÊN TỰ HỌC\n- Ghi chép lại các cấu trúc mới vào sổ tay học tập.\n- Làm bài tập thực hành ở bài học tiếp theo để củng cố kiến thức.', 2040, 1, 0, 1, NOW(), NOW()) ON DUPLICATE KEY UPDATE `title`=VALUES(`title`);
INSERT INTO `lessons` (`id`,`course_section_id`,`title`,`slug`,`type`,`content`,`duration_seconds`,`position`,`is_preview`,`is_published`,`created_at`,`updated_at`) VALUES (176, 83, 'Thực hành ứng dụng & Chữa bài chi tiết: Mệnh đề quan hệ Relative Clauses & Câu điều kiện Conditionals', 'chuong-trinh-course-13-s3-p2-rmbb', 'text', 'MỤC TIÊU BÀI HỌC\n- Vận dụng lý thuyết đã học vào giải các bài tập tình huống thực tế của phần Mệnh đề quan hệ Relative Clauses & Câu điều kiện Conditionals.\n- Rèn luyện phản xạ chính xác và tốc độ xử lý câu hỏi.\n\nBÀI TẬP VẬN DỤNG THỰC TẾ\n- Câu 1: Xác định cấu trúc ngữ pháp và từ khóa chính trong ngữ cảnh bài thi.\n- Câu 2: Áp dụng phương pháp loại trừ để tìm phương án chính xác nhất.\n- Câu 3: Mở rộng từ vựng liên quan và ghi nhớ các cụm từ đồng nghĩa (Paraphrasing).\n\nĐÁP ÁN & GIẢI THÍCH CHI TIẾT\n- Xem lại phần giải thích cho từng câu hỏi, ghi nhận lỗi sai để không lặp lại trong bài thi thật.', 2400, 2, 0, 1, NOW(), NOW()) ON DUPLICATE KEY UPDATE `title`=VALUES(`title`);
