INSERT INTO `lessons` (`id`,`course_section_id`,`title`,`slug`,`type`,`content`,`duration_seconds`,`position`,`is_preview`,`is_published`,`created_at`,`updated_at`) VALUES (207, 99, 'Lý thuyết & Phương pháp trọng tâm: Kỹ năng viết chữ Hán & Bài thi mẫu HSK 3 kèm giải thích chi tiết', 'chuong-trinh-course-32-s4-p1-l860', 'video', 'MỤC TIÊU BÀI HỌC\n- Làm chủ toàn bộ kiến thức nền tảng và phương pháp giải quyết chuyên đề: Kỹ năng viết chữ Hán & Bài thi mẫu HSK 3 kèm giải thích chi tiết.\n- Nhận diện các bẫy thường gặp và quy tắc xử lý nhanh trong bài thi.\n\n1. KIẾN THỨC CỐT LÕI\n- Khái niệm, nguyên lý hoạt động và cấu trúc ngữ pháp / từ vựng then chốt.\n- Các bước tiếp cận đề bài khoa học, tiết kiệm tối đa thời gian.\n\n2. VÍ DỤ VẬN DỤNG & PHÂN TÍCH\n- Phân tích chi tiết các câu hỏi mẫu thực tế từ đề thi chuẩn.\n- Chỉ ra dấu hiệu nhận biết đáp án đúng và lý do loại bỏ các phương án nhiễu.\n\n3. LỜI KHUYÊN TỰ HỌC\n- Ghi chép lại các cấu trúc mới vào sổ tay học tập.\n- Làm bài tập thực hành ở bài học tiếp theo để củng cố kiến thức.', 2160, 1, 0, 1, NOW(), NOW()) ON DUPLICATE KEY UPDATE `title`=VALUES(`title`);
