CREATE DATABASE IF NOT EXISTS `english_center_db` DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE `english_center_db`;
SET NAMES utf8mb4;

-- QR CHUYEN KHOAN NGAN HANG + NOI DUNG KHOA HOC TRONG DATABASE.
-- Import duy nhat file nay vao database hien tai (39, 41, 45 hoac 46 bang).
-- Khong xoa bang, khong doi mat khau. QR chuyen khoan that, admin doi soat truoc khi cap khoa hoc.
-- CUA HANG KHOA HOC + QR CHUYEN KHOAN MB. Chon dung database dang dung truoc khi Import.
-- Nang cap tu 39, 41 hoac 45 len 46 bang. Khong xoa du lieu, khong doi mat khau.
-- QR VietQR chuyen khoan that; admin phai doi soat giao dich truoc khi cap quyen hoc.
-- NANG CAP NOI DUNG WEBSITE: 39 bang -> 41 bang.
-- Chon database dang dung (english_center_db) trong phpMyAdmin truoc khi Import.
-- Khong xoa bang, khong reset tai khoan, giu nguyen noi dung da sua.
SET NAMES utf8mb4;

CREATE TABLE IF NOT EXISTS `public_teachers` (`id` bigint unsigned NOT NULL AUTO_INCREMENT,`name` varchar(255) NOT NULL,`slug` varchar(255) NOT NULL,`bio` text NOT NULL,`photo_path` varchar(255) NOT NULL,`provider` varchar(50) NOT NULL,`source_url` varchar(500) NULL,`qualifications` json NULL,`position` int unsigned NOT NULL DEFAULT 0,`is_active` tinyint(1) NOT NULL DEFAULT 1,`created_at` timestamp NULL,`updated_at` timestamp NULL,PRIMARY KEY (`id`),UNIQUE KEY `public_teachers_slug_unique` (`slug`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `site_settings` (`id` bigint unsigned NOT NULL AUTO_INCREMENT,`key` varchar(255) NOT NULL,`value` json NOT NULL,`created_at` timestamp NULL,`updated_at` timestamp NULL,PRIMARY KEY (`id`),UNIQUE KEY `site_settings_key_unique` (`key`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

START TRANSACTION;
COMMIT;

SET @ec_shop_sql=IF(EXISTS(SELECT 1 FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='courses' AND column_name='is_for_sale'),'SELECT 1 WHERE 0','ALTER TABLE `courses` ADD `is_for_sale` tinyint(1) NOT NULL DEFAULT 0');
PREPARE ec_shop_stmt FROM @ec_shop_sql;
EXECUTE ec_shop_stmt;
DEALLOCATE PREPARE ec_shop_stmt;
CREATE TABLE IF NOT EXISTS `cart_items` (`id` bigint unsigned NOT NULL AUTO_INCREMENT PRIMARY KEY,`user_id` bigint unsigned NOT NULL,`course_id` bigint unsigned NOT NULL,`created_at` timestamp NULL,`updated_at` timestamp NULL,UNIQUE KEY `cart_items_user_id_course_id_unique` (`user_id`,`course_id`),CONSTRAINT `cart_items_user_id_foreign` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE,CONSTRAINT `cart_items_course_id_foreign` FOREIGN KEY (`course_id`) REFERENCES `courses` (`id`) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `orders` (`id` bigint unsigned NOT NULL AUTO_INCREMENT PRIMARY KEY,`number` char(36) NOT NULL UNIQUE,`user_id` bigint unsigned NOT NULL,`checkout_token` char(36) NOT NULL UNIQUE,`buyer_name` varchar(255) NOT NULL,`buyer_email` varchar(255) NOT NULL,`total` bigint unsigned NOT NULL,`currency` varchar(3) NOT NULL DEFAULT 'VND',`status` enum('pending','paid') NOT NULL DEFAULT 'pending',`paid_at` timestamp NULL,`created_at` timestamp NULL,`updated_at` timestamp NULL,INDEX `orders_user_id_status_index` (`user_id`,`status`),CONSTRAINT `orders_user_id_foreign` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `order_items` (`id` bigint unsigned NOT NULL AUTO_INCREMENT PRIMARY KEY,`order_id` bigint unsigned NOT NULL,`course_id` bigint unsigned NOT NULL,`course_name` varchar(255) NOT NULL,`unit_price` bigint unsigned NOT NULL,`access_days` int unsigned NOT NULL,`created_at` timestamp NULL,`updated_at` timestamp NULL,UNIQUE KEY `order_items_order_id_course_id_unique` (`order_id`,`course_id`),CONSTRAINT `order_items_order_id_foreign` FOREIGN KEY (`order_id`) REFERENCES `orders` (`id`) ON DELETE RESTRICT,CONSTRAINT `order_items_course_id_foreign` FOREIGN KEY (`course_id`) REFERENCES `courses` (`id`) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `payments` (`id` bigint unsigned NOT NULL AUTO_INCREMENT PRIMARY KEY,`order_id` bigint unsigned NOT NULL UNIQUE,`reference` varchar(40) NOT NULL UNIQUE,`method` varchar(30) NOT NULL DEFAULT 'demo',`status` enum('pending','paid') NOT NULL DEFAULT 'pending',`amount` bigint unsigned NOT NULL,`confirmed_by` bigint unsigned NULL,`confirmed_at` timestamp NULL,`created_at` timestamp NULL,`updated_at` timestamp NULL,CONSTRAINT `payments_order_id_foreign` FOREIGN KEY (`order_id`) REFERENCES `orders` (`id`) ON DELETE RESTRICT,CONSTRAINT `payments_confirmed_by_foreign` FOREIGN KEY (`confirmed_by`) REFERENCES `users` (`id`) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

START TRANSACTION;
CREATE TABLE IF NOT EXISTS `payment_qr_requests` (`id` bigint unsigned NOT NULL AUTO_INCREMENT PRIMARY KEY,`payment_id` bigint unsigned NOT NULL,`reference` varchar(40) NOT NULL UNIQUE,`bank_snapshot` json NOT NULL,`amount` bigint unsigned NOT NULL,`reported_at` timestamp NULL,`created_at` timestamp NULL,`updated_at` timestamp NULL,CONSTRAINT `payment_qr_requests_payment_id_foreign` FOREIGN KEY (`payment_id`) REFERENCES `payments` (`id`) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
ALTER TABLE `payments` MODIFY `method` varchar(30) NOT NULL DEFAULT 'demo';
COMMIT;
SET @ec_presentation_sql=IF(EXISTS(SELECT 1 FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='courses' AND column_name='catalog_key'),'SELECT 1 WHERE 0','ALTER TABLE `courses` ADD `catalog_key` varchar(50) NULL UNIQUE');
PREPARE ec_presentation_stmt FROM @ec_presentation_sql;
